export async function POST(req:Request){const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);if(req.headers.get('sec-fetch-site')==='cross-site'||(req.headers.get('origin')&&req.headers.get('origin')!==new URL(req.url).origin))return json({error:'Запрос отклонён'},403);if(!req.headers.get('content-type')?.startsWith('application/json'))return json({error:'Ожидается JSON'},415);let parsed;try{const raw=await req.text();if(raw.length>16000)return json({error:'Слишком большой документ'},413);parsed=payload.safeParse(JSON.parse(raw));}catch{return json({error:'Некорректный запрос'},400);}if(!parsed.success)return json({error:'Проверьте обязательные поля, дату и суммы.'},400);const b=parsed.data,owner=ownerFor(req,user.userId),now=new Date().toISOString();try{const d=db();
