if(b.action==='post'){const today=new Date().toISOString().slice(0,10);const r=await d.prepare(`UPDATE documents SET state='posted',posted=? WHERE id=? AND owner=? AND state='draft' AND date<=? AND (kind NOT IN ('receipt','payment') OR EXISTS(SELECT 1 FROM documents parent WHERE parent.id=documents.link AND parent.owner=documents.owner AND parent.state='posted' AND parent.partner=documents.partner AND documents.date>=parent.date AND ((documents.kind='receipt' AND parent.kind='sale') OR (documents.kind='payment' AND parent.kind IN ('purchase','expense'))) AND documents.amount<=parent.amount-COALESCE((SELECT SUM(p.amount) FROM documents p WHERE p.link=parent.id AND p.state='posted' AND p.kind IN ('receipt','payment')),0)))`).bind(now,b.id,owner,today).run();if(!r.meta.changes)return json({error:'Проведение невозможно: проверьте дату, статус документа и остаток к оплате.'},409);return json({ok:true});}
if(!b.reason||b.reason.length<3)return json({error:'Укажите причину отмены'},400);const r=await d.prepare(`UPDATE documents SET state='void',void_reason=? WHERE id=? AND owner=? AND state!='void' AND NOT EXISTS(SELECT 1 FROM documents child WHERE child.link=documents.id AND child.state!='void')`).bind(b.reason,b.id,owner).run();if(!r.meta.changes)return json({error:'Сначала отмените связанные оплаты либо обновите список.'},409);return json({ok:true});
}catch(e){console.error('ERP write failed',e instanceof Error?e.name:'error');return json({error:'Не удалось сохранить. Введённые данные остались в форме.'},503);}}

