import { getChatGPTUser } from '../../chatgpt-auth';
import { changeOneCJobs,createOneCJobSnapshot,oneCJobActionSchema,OneCJobError } from '../../onec-jobs';
import { readOneCJobs,writeOneCJobs } from '../../../db/onec-jobs';
import { readTrade } from '../../../db/trade';

export const dynamic='force-dynamic';
const json=(value:unknown,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'no-store'}});
function scope(req:Request,userId:string){const dataset=new URL(req.url).searchParams.get('dataset');if(dataset!==null&&dataset!=='live'&&dataset!=='demo')throw new OneCJobError('Неизвестная база.');return {owner:dataset==='demo'?userId+':demo':userId,demo:dataset==='demo'};}
export async function GET(req:Request){
  const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);
  try{const current=await readOneCJobs(scope(req,user.userId).owner);return json({revision:current.revision,jobs:current.jobs});}
  catch(e){if(e instanceof OneCJobError)return json({error:e.message},409);console.error('1C queue read failed',e instanceof Error?e.name:'error');return json({error:'Не удалось загрузить очередь 1С.'},503);}
}
export async function POST(req:Request){
  const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);
  const origin=req.headers.get('origin');if(req.headers.get('sec-fetch-site')==='cross-site'||(origin&&origin!==new URL(req.url).origin))return json({error:'Запрос отклонён'},403);
  if(req.headers.get('content-type')?.split(';')[0].trim().toLowerCase()!=='application/json')return json({error:'Ожидается JSON'},415);
  let parsed;try{const raw=await req.text();if(new TextEncoder().encode(raw).byteLength>16_384)return json({error:'Запрос слишком большой'},413);parsed=oneCJobActionSchema.safeParse(JSON.parse(raw));}catch{return json({error:'Некорректный запрос'},400);}
  if(!parsed.success)return json({error:'Проверьте действие, версию и обязательные поля.'},400);
  try{
    const selected=scope(req,user.userId);if(selected.demo)return json({error:'Передача в 1С доступна только в рабочей базе.'},403);
    const current=await readOneCJobs(selected.owner),action=parsed.data;
    let snapshot;
    if(action.action==='enqueue'&&!current.jobs.some(j=>j.documentId===action.documentId))snapshot=createOneCJobSnapshot(action.documentId,action.documentVersion,action.responsible,await readTrade(selected.owner));
    const next=changeOneCJobs(current,action,snapshot);
    if(next!==current&&!await writeOneCJobs(selected.owner,current.revision,next))return json({error:'Очередь изменилась в другом окне. Обновите список и повторите действие.'},409);
    return json({revision:next.revision,jobs:next.jobs});
  }catch(e){if(e instanceof OneCJobError)return json({error:e.message},409);console.error('1C queue write failed',e instanceof Error?e.name:'error');return json({error:'Не удалось изменить очередь 1С.'},503);}
}

