import {getChatGPTUser} from '../../chatgpt-auth';
import {requestActionSchema,requestInputSchema,validateRequest,approveRequest,generateRequestDocuments,RequestError,type SalesRequest} from '../../sales-requests';
import {readSalesRequests,findSalesRequest,writeSalesRequest,commitRequestDocuments} from '../../../db/sales-requests';
import {readTrade} from '../../../db/trade';
import {readSalesWorkspace} from '../../../db/sales-team';
import {readSupplierPrices} from '../../../db/supplier-prices';
import {TradeError} from '../../trade';

export const dynamic='force-dynamic';
const json=(value:unknown,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'no-store'}});
function scope(req:Request,id:string){const dataset=new URL(req.url).searchParams.get('dataset');if(dataset!==null&&dataset!=='demo'&&dataset!=='live')throw new RequestError('Неизвестная база.');return dataset==='demo'?id+':demo':id;}
export async function GET(req:Request){const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);try{return json({requests:await readSalesRequests(scope(req,user.userId))});}catch(e){if(e instanceof RequestError)return json({error:e.message},400);console.error('Request read failed',e instanceof Error?e.name:'error');return json({error:'Не удалось загрузить заявки.'},503);}}
export async function POST(req:Request){
  const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);
  const origin=req.headers.get('origin');if(req.headers.get('sec-fetch-site')==='cross-site'||(origin&&origin!==new URL(req.url).origin))return json({error:'Запрос отклонён'},403);
  if(req.headers.get('content-type')?.split(';')[0].trim().toLowerCase()!=='application/json')return json({error:'Ожидается JSON'},415);
  let parsed;try{const raw=await req.text();if(new TextEncoder().encode(raw).byteLength>250000)return json({error:'Заявка слишком большая'},413);parsed=requestActionSchema.safeParse(JSON.parse(raw));}catch{return json({error:'Некорректный запрос'},400);}
  if(!parsed.success)return json({error:'Проверьте поля, целое количество, цены, даты и ссылки на товары.'},400);
  try{
    const b=parsed.data,owner=scope(req,user.userId),found=await findSalesRequest(b.id),current=found?.request;
    if(found&&found.owner!==owner)return json({error:'Заявка недоступна.'},404);
    if(b.action==='generate'&&current?.state==='documents')return json(current);
    if((current&&current.version!==b.version)||(!current&&b.version!==0))return json({error:'Заявка изменилась или недоступна. Обновите список.'},409);
    if(b.action!=='save'&&!current)return json({error:'Заявка не найдена.'},404);
    const now=new Date().toISOString(),[trade,team,priceBatches]=await Promise.all([readTrade(owner),readSalesWorkspace(owner),readSupplierPrices(owner)]),refs={...trade,members:team.members,priceBatches};
    let next:SalesRequest;
    if(b.action==='save'){
      if(current&&current.state!=='draft')throw new RequestError('Утверждённая заявка заблокирована. Верните её в черновик до создания документов.');
      const input=requestInputSchema.parse(Object.fromEntries(Object.entries(b).filter(([key])=>key!=='action')));validateRequest(input,refs);
      next={...input,state:'draft',version:(current?.version||0)+1,created:current?.created||now,updated:now,approvedAt:'',generated:null};
    }else if(b.action==='approve'){next=approveRequest(current!,refs,now);}
    else if(b.action==='reopen'){
      if(current!.state!=='approved')throw new RequestError('Вернуть в черновик можно только утверждённую заявку без документов.');
      next={...current!,state:'draft',version:current!.version+1,approvedAt:'',updated:now,priceConfirmed:false,deliveryConfirmed:false};
    }else{
      const generated=generateRequestDocuments(current!,refs,trade.documents,trade.revision,now);
      if(!await commitRequestDocuments(owner,current!.version,trade.revision,generated)){
        const after=await findSalesRequest(b.id);if(after?.owner===owner&&after.request.state==='documents')return json(after.request);
        return json({error:'Данные изменились. Обновите заявку и справочники перед повтором.'},409);
      }
      return json(generated.request);
    }
    if(!await writeSalesRequest(owner,current?.version||0,next))return json({error:'Заявка изменилась или достигнут предел 200 заявок. Обновите список.'},409);
    return json(next);
  }catch(e){if(e instanceof RequestError||e instanceof TradeError)return json({error:e.message},409);console.error('Request write failed',e instanceof Error?e.name:'error');return json({error:'Не удалось сохранить заявку. Повторите после обновления.'},503);}
}

