import { getChatGPTUser } from '../../chatgpt-auth';
import { salesActionSchema,initializeSalesWorkspace,changeSalesWorkspace,SalesError } from '../../sales-team';
import { readSalesWorkspace,writeSalesWorkspace } from '../../../db/sales-team';
import { readTrade } from '../../../db/trade';

export const dynamic='force-dynamic';
const json=(value:unknown,status=200)=>Response.json(value,{status,headers:{'Cache-Control':'no-store'}});
function scope(req:Request,userId:string) {
  const dataset=new URL(req.url).searchParams.get('dataset');
  if(dataset!==null&&dataset!=='live'&&dataset!=='demo')throw new SalesError('Неизвестная база.');
  return {owner:dataset==='demo'?userId+':demo':userId,demo:dataset==='demo'};
}
export async function GET(req:Request) {
  const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);
  try{return json(await readSalesWorkspace(scope(req,user.userId).owner));}
  catch(e){if(e instanceof SalesError)return json({error:e.message},400);console.error('Sales workspace read failed',e instanceof Error?e.name:'error');return json({error:'Не удалось загрузить команду.'},503);}
}
export async function POST(req:Request) {
  const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);
  const origin=req.headers.get('origin');
  if(req.headers.get('sec-fetch-site')==='cross-site'||(origin&&origin!==new URL(req.url).origin))return json({error:'Запрос отклонён'},403);
  if(req.headers.get('content-type')?.split(';')[0].trim().toLowerCase()!=='application/json')return json({error:'Ожидается JSON'},415);
  let parsed;
  try{const raw=await req.text();if(new TextEncoder().encode(raw).byteLength>64000)return json({error:'Запрос слишком большой'},413);parsed=salesActionSchema.safeParse(JSON.parse(raw));}
  catch{return json({error:'Некорректный запрос'},400);}
  if(!parsed.success)return json({error:'Проверьте обязательные поля, даты и длину текста.'},400);
  try {
    const {owner,demo}=scope(req,user.userId),current=await readSalesWorkspace(owner),action=parsed.data;
    if(action.action==='initialize'&&current.revision>0)return json(current);
    if(action.action!=='initialize'&&action.revision!==current.revision)return json({error:'Данные изменились в другом окне. Обновите список.'},409);
    const refs=await readTrade(owner);
    const next=action.action==='initialize'?await initializeSalesWorkspace(owner,demo,refs):changeSalesWorkspace(current,action,refs);
    if(!await writeSalesWorkspace(owner,current.revision,next)) {
      if(action.action==='initialize')return json(await readSalesWorkspace(owner));
      return json({error:'Данные изменились в другом окне. Обновите список и повторите действие.'},409);
    }
    return json({...next,revision:current.revision+1});
  }catch(e){if(e instanceof SalesError)return json({error:e.message},409);console.error('Sales workspace write failed',e instanceof Error?e.name:'error');return json({error:'Не удалось сохранить изменения. Данные остались в форме.'},503);}
}

