const amount=z.number().int().min(0).max(100000000000);
const payload=z.discriminatedUnion('action',[
 z.object({action:z.literal('save'),id:uuid,version:z.number().int().min(0),kind:z.enum(['customer_order','supplier_order','invoice','sale','purchase','receipt','payment','expense','transfer','stock_in','stock_out']),number:z.string().trim().max(60),date:day,due:z.union([day,z.literal('')]),partner:ref,organization:uuid,warehouse:ref,target:ref,basis:ref,note:z.string().trim().max(2000),amount,channel:z.enum(['bank','cash']),lines:z.array(z.object({item:uuid,qty:z.number().int().positive().max(1000000000),price:amount})).max(50)}),
 z.object({action:z.literal('post'),id:uuid,version:z.number().int().min(1)}),
 z.object({action:z.literal('void'),id:uuid,version:z.number().int().min(1),reason:z.string().trim().min(3).max(500)}),
 z.object({action:z.literal('seed')})
]);
const json=(v:unknown,status=200)=>Response.json(v,{status,headers:{'Cache-Control':'no-store'}});
const scope=(req:Request,id:string)=>new URL(req.url).searchParams.get('dataset')==='demo'?id+':demo':id;
export async function GET(req:Request){const user=await getChatGPTUser();if(!user)return json({error:'Войдите в систему'},401);try{const data=await readTrade(scope(req,user.userId));return json({documents:data.documents,revision:data.revision});}catch(e){console.error('Trade read failed',e instanceof Error?e.name:'error');return json({error:'Не удалось загрузить торговые документы.'},503);}}
