files.app/dark-theme.css:
/* Shared dark palette for the entire accounting workspace. */
:root {
  --background: #0c1420;
  --foreground: #e3ebf5;
  --primary: #158bd2;
  --muted: #9baec3;
  --border: #28374b;
  --card: #142031;
  color-scheme: dark;
  scrollbar-color: #42546b #101b2a;
}

body { background: var(--background); color: var(--foreground); }
header { background: #111c2b; }
.sidebar { background: #0e1b2b; border-right: 1px solid var(--border); }
.company { background: #192a3d; border-color: #2b4057; }
.company-avatar, .user-mini { background: #263c53; color: #c9e4f7; }
.sidebar nav button:hover { background: #20354b; }
.sidebar nav button.active { background: #116da9; }
.nav-caption, .storage-label, .user small, .company small { color: #91a8bd; }
.brand-tag { color: #a8bfd2; border-color: #46627b; }
.breadcrumbs, .currency { color: #94a8be; }
.breadcrumbs strong, .header-tools button { color: #bdcede; }
.eyebrow, .page-title p, .period > span, .muted-small,
.panel-title p, .legend, .chart-month > span, .chart-footer,
.settlement-item div > span, .settlement-bottom, .doc-link small,
.table-bottom, .quiet-empty, .report-note, footer, footer button,
.payment-list > button > span, .payment-list small,
.partner-card p, .partner-card > div, .form-bottom > span {
  color: var(--muted);
}

.panel, .kpi, .partner-card { background: var(--card); border-color: var(--border); }
.kpi-top, .kpi-top svg { color: #a7bad0; }
.kpi small { color: #9badc3; }
.kpi-1 { background: #122e2c; border-color: #26504a; }
.kpi-1 strong { color: #70d9b6; }
.kpi-1 .kpi-top, .kpi-1 .kpi-top svg, .kpi-1 small { color: #a0c9bd; }
.primary { background: #137cb9; box-shadow: 0 3px 12px #0003; }
.primary:hover { background: #178dce; }
.secondary, .period input, .list-toolbar select, .dataset-switch {
  background: #1a2a3d;
  border-color: #354b64;
  color: #d0dfed;
}
.secondary:hover { background: #243950; border-color: #54708d; }
.onboarding { background: #142d45; border-color: #2b4d6b; }
.onboarding-icon { color: #78c5f5; }
.onboarding p { color: #a0bad2; }
.onboarding .secondary { background: #213f5b; }
.chart-grid span { border-color: #304156; color: #93a6bd; }
.bar, .legend i { background: #43a8e8; }
.bar.costs, .legend span + span i { background: #547594; }
.chart-footer strong { color: #d5e5f4; }
.green { background: #193b35; color: #75d6b4; }
.orange { background: #3e3126; color: #f0be8e; }
.settlement-bottom b, .count { background: #23354b; color: #becde0; }
.text-button, .sample-link { color: #79c7f7; }

th { background: #101b2a; color: #9eb2c9; border-color: var(--border); }
td { color: #b6c6d9; border-color: var(--border); }
td.numeric, .doc-link { color: #e0eaf6; }
tbody tr:hover, .payment-list > button:hover { background: #1b2e44; }
.doc-symbol { background: #1e3a59; color: #8cc8f5; }
.receipt { background: #1a3a33; color: #82d7b2; }
.payment { background: #3b2f25; color: #eac095; }
.badge { background: #2b3b51; color: #cad7e7; }
.badge.posted { background: #193d32; color: #87dcb4; }
.badge.draft { background: #413722; color: #eed092; }
.badge.void { background: #422b35; color: #e6abb9; }
.empty { color: #9bafc7; }
.empty h3 { color: #c4d5e7; }
.payment-list > button, .partner-card > div, .report-line { border-color: var(--border); }
.payment-list .late { color: #efa998; }
.search { background: #111e2f; border-color: #354b64; color: #9cb3cd; }
.search input { color: #e3ebf5; }
.partner-avatar { background: #203b58; color: #8bcbf7; }
.report-line { color: #afc1d4; }
.report-line strong { color: #e3ebf5; }
.report-line:last-child { background: #1c3248; color: #8acdf8; }

dialog { background: #172436; color: #e3ebf5; border-color: #3a506a; box-shadow: 0 25px 100px #0009; }
dialog::backdrop { background: #020812bb; }
.close, .modal-sub, dt, .help-steps p { color: #a8bcd2; }
.close:hover { background: #2b4059; color: #fff; border-radius: 5px; }
form label { color: #c1d1e3; }
form input, form textarea, form select { background: #0e1b2b; border-color: #3c516b; color: #e3ebf5; }
form small { color: #dfbc84; }
input::placeholder, textarea::placeholder { color: #8fa3bb; opacity: 1; }
.cancel-section { border-color: var(--border); color: #d6afbb; }
.help-steps b { color: #cee5f8; }
.error { background: #3b2329; border-color: #72404a; color: #ffc0b5; }
.toast { background: #234660; border: 1px solid #467797; box-shadow: 0 7px 35px #0006; }

.demo-banner { background: #302b20; border-color: #5a492c; }
.demo-badge { background: #4c3f26; color: #f0cc87; }
.demo-banner strong { color: #f0cf91; }
.demo-banner p { color: #caba98; }
.catalog-tabs { border-color: var(--border); }
.catalog-tabs button { color: #acbfd4; }
.catalog-tabs button:hover { background: #20364d; }
.catalog-tabs .selected { background: #1e4060; color: #95d5fd; }
.catalog-tabs span { background: #2c435c; color: #c4d9ed; }
:focus-visible { outline: 2px solid #78c8ff; }
.search:focus-within { outline: 2px solid #78c8ff; }
::selection { background: #285d85; color: #fff; }

