'use client';
import {useEffect,useState,useRef} from 'react';
import {createPortal} from 'react-dom';
import {X,Plus,Search,Pencil,ChevronDown,Check} from 'lucide-react';
import type {Catalog,Partner} from './logic';
import {money} from './logic';
import {catalogMeta,decimal,productMatches} from './line-entry';

export type DirectoryKind='product'|'partner'|'organization'|'warehouse'|'category';
export const directoryNames:Record<DirectoryKind,string>={product:'Номенклатура',partner:'Контрагенты',organization:'Организации',warehouse:'Склады',category:'Статьи расходов'};
export type SaveDirectory=(payload:unknown)=>Promise<void>;
export function FloatingDialog({title,children,onClose,busy=false,wide=false}:{title:string;children:React.ReactNode;onClose:()=>void;busy?:boolean;wide?:boolean}){
 const [mounted,setMounted]=useState(false),dialog=useRef<HTMLDialogElement>(null);useEffect(()=>setMounted(true),[]);
 useEffect(()=>{if(!mounted||!dialog.current)return;const node=dialog.current,previous=document.activeElement as HTMLElement|null;node.showModal();node.querySelector<HTMLInputElement>('[data-initial-focus]')?.focus();return()=>{node.close();if(previous?.isConnected)previous.focus();};},[mounted]);
 return mounted?createPortal(<dialog aria-label={title} className={'reference-dialog '+(wide?'reference-wide':'')} ref={dialog} onCancel={e=>{e.preventDefault();e.stopPropagation();if(!busy)onClose();}} onClick={e=>e.stopPropagation()} onKeyDown={e=>e.stopPropagation()}><button type="button" className="close" aria-label={'Закрыть: '+title} disabled={busy} onClick={onClose}><X size={20}/></button>{children}</dialog>,document.body):null;
}
export function DirectoryEditor({kind,record,catalogs,save,onClose,onSaved,partnerRole='both'}:{kind:DirectoryKind;record?:Catalog|Partner;catalogs:Catalog[];save:SaveDirectory;onClose:()=>void;onSaved:(id:string)=>void;partnerRole?:string}){
 const [id]=useState(()=>record?.id||crypto.randomUUID()),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const c=record as Catalog|undefined,p=record as Partner|undefined,m=catalogMeta(c);
 const groups=[...new Set(catalogs.filter(c=>c.kind==='product').map(c=>catalogMeta(c).group).filter(Boolean))].sort();
 const prefix={product:'НМ',organization:'ОРГ',warehouse:'СКЛ',category:'СТ',partner:'КА'}[kind];
 const suggestion=()=>{let n=catalogs.filter(c=>c.kind===kind).length+1;while(catalogs.some(c=>c.kind===kind&&c.code===prefix+'-'+String(n).padStart(5,'0')))n++;return prefix+'-'+String(n).padStart(5,'0');};
 async function submit(e:React.FormEvent<HTMLFormElement>){
  e.preventDefault();e.stopPropagation();setBusy(true);setError('');const f=Object.fromEntries(new FormData(e.currentTarget));
  try{
   if(kind==='partner')await save({action:record?'partner_edit':'partner',id,name:f.name,inn:f.inn,role:f.role,contact:f.contact,...(record?{original:{name:p!.name,inn:p!.inn,role:p!.role,contact:p!.contact}}:{})});
   else await save({action:'catalog',id,kind,code:f.code,name:f.name,unit:kind==='product'?f.unit:'',price:kind==='product'?decimal(String(f.price||'0'),2):0,note:f.note,item_type:kind==='product'?f.item_type:'goods',details:{...m,...Object.fromEntries((kind==='organization'?['inn','kpp','address','bank','bik','account','corr']:kind==='product'?['article','barcode','group']:[]).map(k=>[k,f[k]||'']))}});
   onSaved(id);
  }catch(e){setError(e instanceof Error?e.message:'Не удалось сохранить запись.');}finally{setBusy(false);}
 }
 return <FloatingDialog title={record?'Карточка справочника':'Новая запись справочника'} busy={busy} onClose={onClose}><span className="eyebrow">{directoryNames[kind]}</span><h2>{record?'Карточка записи':'Создать запись'}</h2><form onSubmit={submit} className="directory-form"><fieldset disabled={busy}>
  <div className="form-grid">{kind!=='partner'&&<label>Код<input name="code" required maxLength={40} defaultValue={c?.code||suggestion()}/></label>}<label>Наименование<input name="name" required minLength={2} maxLength={180} defaultValue={record?.name||''} data-initial-focus="true"/></label></div>
  {kind==='partner'?<><div className="form-grid"><label>ИНН<input name="inn" pattern="(\d{10}|\d{12})?" defaultValue={p?.inn||''} placeholder="10 или 12 цифр"/></label><label>Роль<select name="role" defaultValue={p?.role||partnerRole}><option value="both">Покупатель и поставщик</option><option value="customer">Покупатель</option><option value="supplier">Поставщик</option></select></label></div><label>Контакт<input name="contact" maxLength={250} defaultValue={p?.contact||''} placeholder="Имя, телефон, email"/></label></>:<>
   {kind==='product'&&<><div className="form-grid"><label>Артикул<input name="article" maxLength={80} defaultValue={m.article||''}/></label><label>Штрихкод<input name="barcode" maxLength={64} defaultValue={m.barcode||''}/></label><label>Группа<input name="group" list={'groups-'+id} maxLength={120} defaultValue={m.group||''} placeholder="Например, Крепёж"/><datalist id={'groups-'+id}>{groups.map(g=><option key={g} value={g}/>)}</datalist></label><label>Вид номенклатуры<select name="item_type" defaultValue={c?.item_type||'goods'}><option value="goods">Товар</option><option value="service">Услуга</option></select></label><label>Единица измерения<input name="unit" required maxLength={30} defaultValue={c?.unit||'шт'}/></label><label>Справочная цена, ₽<input name="price" required inputMode="decimal" defaultValue={String((c?.price||0)/100)}/></label></div><p className="reference-hint">Цена подставляется в новые строки. Изменение справочника не меняет цены сохранённых документов. Группа — текстовая метка.</p></>}
   {kind==='organization'&&<><h3>Реквизиты для счетов</h3><div className="form-grid">{[['inn','ИНН'],['kpp','КПП'],['bank','Банк'],['bik','БИК'],['account','Расчётный счёт'],['corr','Корреспондентский счёт'],['address','Адрес']].map(([key,label])=><label key={key}>{label}<input name={key} maxLength={key==='address'?400:200} defaultValue={m[key]||''}/></label>)}</div></>}
   <label>Примечание<textarea name="note" maxLength={1000} rows={2} defaultValue={c?.note||''}/></label>
  </>}
  {error&&<div className="error" role="alert">{error}</div>}<div className="reference-footer"><span>{record?'Изменения сохраняются в справочнике':'Запись будет доступна в документах текущей базы'}</span><button className="primary" type="submit"><Check size={16}/>{busy?'Сохраняем…':'Записать и закрыть'}</button></div>
 </fieldset></form></FloatingDialog>;
}

