type Props={lines:EditLine[];onChange:(lines:EditLine[])=>void;kind:TradeKind;basis:string;organization:string;warehouse:string;catalogs:Catalog[];partners:Partner[];documents:TradeDoc[];saveDirectory:SaveDirectory};
export default function DocumentLines(props:Props){
