 function choose(index:number,id:string){if(lines.some((l,n)=>n!==index&&l.item===id)){setError('Этот товар уже есть в таблице. Измените количество в существующей строке или используйте подбор.');return;}const c=catalogs.find(c=>c.id===id),source=parent?.lines.find(l=>l.item===id);update(lines.map((l,n)=>n===index?{...l,item:id,price:String((autoCost?0:source?.price??c?.price??0)/100)}:l));}
 function move(offset:number){if(selected.length!==1)return;const i=selected[0],j=i+offset;if(j<0||j>=lines.length)return;const next=[...lines];[next[i],next[j]]=[next[j],next[i]];update(next);setSelected([j]);}
 function nextCell(e:React.KeyboardEvent<HTMLInputElement>,index:number,column:string){if(e.key==='Enter'){e.preventDefault();const next=grid.current?.querySelector<HTMLInputElement>(`input[data-row="${index+1}"][data-column="${column}"]`);next?.focus();next?.select();}}
 return <section className="document-lines" aria-label="Табличная часть товаров"><div className="document-lines-caption"><h3>Товары и услуги <span>{lines.filter(l=>l.item).length}</span></h3><small>Цены и суммы в рублях</small></div><div className="grid-toolbar"><button className="primary" type="button" onClick={()=>setPicker(true)}><Package size={16}/>Подбор</button><button className="secondary" type="button" onClick={add} disabled={lines.length>=50}><Plus size={16}/>Добавить</button><button className="secondary" type="button" disabled={!selected.length} onClick={()=>{const next=lines.filter((_,i)=>!selected.includes(i));update(next.length?next:[{item:'',qty:'1',price:'0'}]);setSelected([]);}}><Trash2 size={15}/>Удалить{selected.length?' ('+selected.length+')':''}</button><button className="grid-icon" type="button" aria-label="Переместить строку вверх" disabled={selected.length!==1||selected[0]===0} onClick={()=>move(-1)}><ArrowUp size={16}/></button><button className="grid-icon" type="button" aria-label="Переместить строку вниз" disabled={selected.length!==1||selected[0]>=lines.length-1} onClick={()=>move(1)}><ArrowDown size={16}/></button><span>Tab — ячейка · Enter — следующая строка</span></div>
