}

function ProductPicker({products,lines,kind,basis,organization,warehouse,catalogs,documents,saveDirectory,limits,onHand,onApply,onClose}:{products:Catalog[];limits:Record<string,number>;onHand:(id:string)=>number;onApply:(lines:EditLine[])=>void;onClose:()=>void}&Props){
 const [query,setQuery]=useState(''),[group,setGroup]=useState('all'),[onlyStock,setOnlyStock]=useState(false),[basket,setBasket]=useState<Record<string,EditLine>>({}),[error,setError]=useState(''),[create,setCreate]=useState(false);
