import {fulfilled,settlements,stockRows,type TradeDoc} from './trade';
import {remaining,type Doc} from './logic';

export type Reference={id:string;source:'trade'|'legacy'};
export type AlertKind='money'|'delivery'|'stock'|'margin'|'quality';
export type Insight={id:string;kind:AlertKind;severity:'critical'|'warning'|'info';title:string;detail:string;action:string;amount?:number;days:number;refs:Reference[];evidence:string[]};
export type CashEvent={ref:Reference;number:string;partner:string;organization:string;due:string;incoming:boolean;debt:number;planned:number};
export type Coverage={key:string;organization:string;warehouse:string;item:string;name:string;unit:string;onHand:number;demand:number;incoming:number;lateIncoming:number;undatedIncoming:number;undatedDemand:number;shortNow:number;shortOnDates:number;shortAfter:number;firstDue:string;riskDue:string;refs:Reference[]};
export type ControlOptions={asOf:string;horizon:number;organization?:string;marginPercent?:number};
export const shiftDay=(date:string,days:number)=>new Date(Date.parse(date+'T12:00:00Z')+days*86400000).toISOString().slice(0,10);
const daysBetween=(a:string,b:string)=>Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000);
const ref=(d:{id:string},source:'trade'|'legacy'='trade'):Reference=>({id:d.id,source});
const stockKey=(o:string,w:string,i:string)=>JSON.stringify([o,w,i]);
const qty=(q:number)=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:3}).format(q/1000);
const rub=(n:number)=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB'}).format(n/100);

/** Current-state analysis. asOf is today's business date, not a historical ledger. */
export function analyzeControl(trade:TradeDoc[],legacy:Doc[],options:ControlOptions){
 const {asOf,organization='',marginPercent=15}=options;
 const horizon=Math.max(1,Math.min(90,Math.floor(options.horizon))),end=shiftDay(asOf,horizon-1);
 const docs=trade.filter(d=>d.date<=asOf&&(!organization||d.organization===organization));
 const old=legacy.filter(d=>d.date<=asOf&&(!organization||d.organization===organization));
 const alerts:Insight[]=[],events:CashEvent[]=[];
 for(const r of settlements(docs))if(r.planned>0)events.push({ref:ref(r.doc),number:r.doc.number,partner:r.doc.partner,organization:r.doc.organization,due:r.doc.due,incoming:r.customer,debt:r.debt,planned:r.planned});
 for(const d of old.filter(d=>d.state==='posted'&&['sale','purchase','expense'].includes(d.kind))){
  const debt=Math.max(0,remaining(d,old));if(debt)events.push({ref:ref(d,'legacy'),number:d.number,partner:d.partner,organization:d.organization,due:d.due,incoming:d.kind==='sale',debt,planned:debt});
 }
 const openOrders=docs.filter(d=>d.state==='posted'&&['customer_order','supplier_order'].includes(d.kind)).map(d=>({doc:d,lines:d.lines.map(l=>({...l,left:Math.max(0,l.qty-fulfilled(d,l.item,docs))})).filter(l=>l.left>0)})).filter(r=>r.lines.length>0);
 const missingDue=new Map<string,{reference:Reference;number:string}>();
 for(const e of events){
  if(!e.due){missingDue.set(e.ref.id,{reference:e.ref,number:e.number});continue;}
  if(e.debt<=0)continue;
  const overdue=e.due<asOf;
  if(overdue||e.due<=shiftDay(asOf,2))alerts.push({id:'money:'+e.ref.id,kind:'money',severity:overdue?'critical':'warning',title:overdue?(e.incoming?'Покупатель просрочил оплату':'Просрочена оплата поставщику'):(e.incoming?'Проверить ближайшее поступление':'Подготовить ближайшую оплату'),detail:`№ ${e.number} · срок ${e.due}`,action:e.incoming?'Проверить долг и оплату':'Проверить основание оплаты',amount:e.debt,days:overdue?daysBetween(e.due,asOf):0,refs:[e.ref],evidence:[`Текущий долг: ${rub(e.debt)}. Учитываются только проведённые поставки, расходы и оплаты.`,`Ожидается по документу всего: ${rub(e.planned)}. Сумма сверх долга относится к ещё не оплаченному плану.`,...(e.ref.source==='legacy'?['Прежний документ без товарных строк.']:['Срок взят из общего поля «Срок поставки / оплаты» основания.'])]});
 }
 for(const {doc,lines} of openOrders){
  if(!doc.due){missingDue.set(doc.id,{reference:ref(doc),number:doc.number});continue;}
  if(doc.due>shiftDay(asOf,2))continue;
  const overdue=doc.due<asOf;
  alerts.push({id:'delivery:'+doc.id,kind:'delivery',severity:overdue?'critical':'warning',title:doc.kind==='customer_order'?(overdue?'Отгрузка просрочена':'Приближается срок отгрузки'):(overdue?'Поставка отстаёт от срока':'Подтвердить ближайшую поставку'),detail:`Заказ № ${doc.number} · срок ${doc.due}`,action:doc.kind==='customer_order'?'Открыть заказ и отгрузку':'Открыть заказ поставщику',days:overdue?daysBetween(doc.due,asOf):0,refs:[ref(doc)],evidence:[...lines.map(l=>`${l.name}: осталось ${qty(l.left)} ${l.unit} из ${qty(l.qty)} ${l.unit}.`),'Частичные накладные учтены. Используется общее поле срока поставки / оплаты заказа.']});
 }
 for(const m of missingDue.values())alerts.push({id:'date:'+m.reference.id,kind:'quality',severity:'info',title:'Указать срок по открытому документу',detail:`№ ${m.number} не попадает в календарь платежей без даты.`,action:'Открыть документ',days:0,refs:[m.reference],evidence:['Есть незакрытая поставка или ожидаемая оплата. Срок не задан; система не считает её просроченной.','Проведённый документ нельзя редактировать: исправление выполняется через отмену зависимых документов и новое основание.']});

 const balances=stockRows(docs),groups=new Map<string,Coverage>();
