import type {Catalog} from './logic';
export type EditLine={item:string;qty:string;price:string};
export function catalogMeta(row?:Catalog):Record<string,string>{
 try{const value=JSON.parse(row?.details||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{return {};}
}
export function productMatches(row:Catalog,query:string){const m=catalogMeta(row);return query.toLocaleLowerCase('ru').trim().split(/\s+/).every(word=>`${row.name} ${row.code} ${m.article||''} ${m.barcode||''} ${m.group||''}`.toLocaleLowerCase('ru').includes(word));}
export function decimal(value:string,digits:number){
 const s=value.trim().replace(',','.');if(!new RegExp('^\\d+(?:\\.\\d{1,'+digits+'})?$').test(s))throw new Error(`Введите число с точностью до ${digits} знаков после запятой.`);
 const [whole,fraction='']=s.split('.'),n=Number(whole)*10**digits+Number(fraction.padEnd(digits,'0'));if(!Number.isSafeInteger(n))throw new Error('Слишком большое число.');return n;
}
export function lineValue(line:EditLine):number|null{
 try{const q=decimal(line.qty,3),p=decimal(line.price,2);if(q<=0||q>1000000000||p>100000000000)return null;const n=Number((BigInt(q)*BigInt(p)+BigInt(500))/BigInt(1000));return n<=100000000000?n:null;}catch{return null;}
}
/** Re-picking adds quantity once and retains the price already entered in the document. */
export function mergePickedLines(existing:EditLine[],picked:EditLine[],limits:Record<string,number>={}){
 const result=existing.filter(l=>l.item).map(l=>({...l}));
 for(const p of picked){
  if(!p.item)throw new Error('Выберите номенклатуру.');
  const q=decimal(p.qty,3);if(q<=0||q>1000000000||lineValue(p)===null)throw new Error('Проверьте количество и цену выбранных товаров.');
  const old=result.find(l=>l.item===p.item),total=q+(old?decimal(old.qty,3):0);
  if(total>1000000000)throw new Error('Количество не может превышать 1 000 000.');
  if(limits[p.item]!==undefined&&total>limits[p.item])throw new Error('Количество превышает остаток по заказу. Уменьшите количество в подборе или в документе.');
  if(old)old.qty=String(total/1000);else result.push({...p});
 }
 if(result.length>50)throw new Error('В документе может быть не более 50 разных позиций.');
 if(result.some(l=>lineValue(l)===null)||result.reduce((s,l)=>s+(lineValue(l)||0),0)>100000000000)throw new Error('Проверьте количество, цену и общую сумму документа.');
 return result;
}

