import { z } from 'zod';
import { lineAmount, type TradeDoc } from './trade';
import type { Catalog, Partner } from './logic';

export const ONEC_JOB_LIMIT=500;
export const ONEC_RUNNING_TIMEOUT_MS=10*60*1000;
export const oneCJobStatuses=['queued','running','needs_attention','saved','cancelled'] as const;
export type OneCJobStatus=typeof oneCJobStatuses[number];
export type OneCJobLine={item:string;name:string;code:string;article:string;unit:string;qty:number;price:number;amount:number};
export type OneCJobSnapshot={
  documentId:string;documentVersion:number;partner:{id:string;name:string;inn:string};
  organization:{id:string;name:string};warehouse:{id:string;name:string};lines:OneCJobLine[];
  amount:number;date:string;due:string;note:string;responsible:string;
};
export type OneCJob={
  id:string;marker:string;documentId:string;documentVersion:number;snapshot:OneCJobSnapshot;
  status:OneCJobStatus;runId:string;message:string;number:string;reference:string;
  createdAt:string;updatedAt:string;startedAt:string;
};
export type OneCJobsWorkspace={revision:number;jobs:OneCJob[]};
export type OneCJobReferences={documents:TradeDoc[];catalogs:Catalog[];partners:Partner[]};
export class OneCJobError extends Error {}
const check:(condition:unknown,message:string)=>asserts condition=(condition,message)=>{if(!condition)throw new OneCJobError(message);};
const uuid=z.string().uuid();
const revision=z.number().int().min(0);
const text=(min:number,max:number)=>z.string().trim().min(min).max(max);
const reference=z.string().trim().max(500).regex(/^e1cib\/data\/Документ\.ЗаказПокупателя\?ref=[0-9A-Fa-f]{32}$/);
export const oneCJobActionSchema=z.discriminatedUnion('action',[
  z.object({action:z.literal('enqueue'),revision,documentId:uuid,documentVersion:z.number().int().min(1),responsible:text(1,120)}).strict(),
  z.object({action:z.literal('claim'),revision,id:uuid,runId:uuid}).strict(),
  z.object({action:z.literal('attention'),revision,id:uuid,runId:uuid,message:text(1,1000)}).strict(),
  z.object({action:z.literal('saved'),revision,id:uuid,runId:uuid,number:text(1,80),reference}).strict(),
  z.object({action:z.literal('cancel'),revision,id:uuid}).strict(),
]);
export type OneCJobAction=z.infer<typeof oneCJobActionSchema>;

export const emptyOneCJobsWorkspace=():OneCJobsWorkspace=>({revision:0,jobs:[]});
function meta(c:Catalog){try{const value=JSON.parse(c.details||'{}') as unknown;return value&&typeof value==='object'?value as Record<string,unknown>:{};}catch{return {};}}
export function createOneCJobSnapshot(documentId:string,documentVersion:number,responsible:string,refs:OneCJobReferences):OneCJobSnapshot{
  const doc=refs.documents.find(d=>d.id===documentId);
  check(doc,'Заказ покупателя не найден.');
  check(doc.kind==='customer_order'&&(doc.state==='draft'||doc.state==='posted'),'В 1С можно передать только активный заказ покупателя.');
  check(doc.version===documentVersion,'Заказ уже изменён. Обновите список перед передачей в 1С.');
  const partner=refs.partners.find(p=>p.id===doc.partner);
  const organization=refs.catalogs.find(c=>c.id===doc.organization&&c.kind==='organization');
  const warehouse=refs.catalogs.find(c=>c.id===doc.warehouse&&c.kind==='warehouse');
  check(doc.partner&&partner,'Контрагент заказа отсутствует в текущей базе.');
  check(doc.organization&&organization,'Организация заказа отсутствует в текущей базе.');
  check(doc.warehouse&&warehouse,'Склад заказа отсутствует в текущей базе.');
  check(doc.lines.length>0&&doc.lines.length<=50,'Заказ должен содержать от 1 до 50 строк.');
  check(new Set(doc.lines.map(line=>line.item)).size===doc.lines.length,'Номенклатура в строках заказа не должна повторяться.');
  const lines=doc.lines.map(line=>{
    const item=refs.catalogs.find(c=>c.id===line.item&&c.kind==='product');
    check(line.item&&item,'Номенклатура строки отсутствует в текущей базе.');
    check(line.unit===item.unit,'Единица измерения строки не совпадает с текущим справочником.');
    check(line.type===(item.item_type||'goods'),'Тип номенклатуры строки не совпадает с текущим справочником.');
    check(Number.isSafeInteger(line.qty)&&line.qty>0&&line.qty<=1_000_000_000,'Количество в строке некорректно.');
    check(Number.isSafeInteger(line.price)&&line.price>=0&&line.price<=100_000_000_000,'Цена в строке некорректна.');
    const amount=lineAmount(line.qty,line.price);
    check(line.amount===amount&&Number.isSafeInteger(amount),'Сумма строки не совпадает с количеством и ценой.');
    const details=meta(item),article=typeof details.article==='string'?details.article:'';
    return {item:item.id,name:item.name,code:item.code,article,unit:item.unit,qty:line.qty,price:line.price,amount};
  });
  const amount=lines.reduce((sum,line)=>sum+line.amount,0);
  check(Number.isSafeInteger(doc.amount)&&doc.amount>=0&&doc.amount<=100_000_000_000,'Сумма заказа превышает допустимый предел.');
  check(doc.amount===amount,'Сумма заказа не совпадает с суммой строк.');
  return {documentId:doc.id,documentVersion:doc.version,partner:{id:partner.id,name:partner.name,inn:partner.inn},organization:{id:organization.id,name:organization.name},warehouse:{id:warehouse.id,name:warehouse.name},lines,amount,date:doc.date,due:doc.due,note:doc.note,responsible:responsible.trim()};
}

export function markStaleOneCJobs(workspace:OneCJobsWorkspace,now=new Date().toISOString()):OneCJobsWorkspace{
  const cutoff=Date.parse(now)-ONEC_RUNNING_TIMEOUT_MS;let changed=false;
  const jobs=workspace.jobs.map(job=>{
    if(job.status!=='running'||!job.startedAt||Date.parse(job.startedAt)>=cutoff)return job;
    changed=true;return {...job,status:'needs_attention' as const,message:job.message||'Нет подтверждения от 1С более 10 минут. Проверьте результат вручную.',updatedAt:now};
  });
  return changed?{revision:workspace.revision,jobs}:workspace;
}

export function changeOneCJobs(workspace:OneCJobsWorkspace,action:OneCJobAction,snapshot?:OneCJobSnapshot,now=new Date().toISOString()):OneCJobsWorkspace{
  const duplicate=action.action==='enqueue'?workspace.jobs.find(j=>j.documentId===action.documentId):undefined;
  if(duplicate)return workspace;
  if(action.action==='claim'){
    const same=workspace.jobs.find(j=>j.id===action.id&&j.runId===action.runId);
    if(same)return workspace;
  }
  if(action.action==='saved'){
    const same=workspace.jobs.find(j=>j.id===action.id&&j.runId===action.runId&&j.status==='saved'&&j.number===action.number&&j.reference===action.reference);
    if(same)return workspace;
  }
  if(action.revision!==workspace.revision)throw new OneCJobError('Очередь изменилась в другом окне. Обновите список.');
  const jobs=[...workspace.jobs];
  if(action.action==='enqueue'){
    check(snapshot&&snapshot.documentId===action.documentId&&snapshot.documentVersion===action.documentVersion,'Не удалось подготовить точный снимок заказа.');
    check(jobs.length<ONEC_JOB_LIMIT,'В очереди достигнут предел 500 заданий.');
    const id=crypto.randomUUID();jobs.push({id,marker:'ATLAS-'+id,documentId:action.documentId,documentVersion:action.documentVersion,snapshot,status:'queued',runId:'',message:'',number:'',reference:'',createdAt:now,updatedAt:now,startedAt:''});
  }else{
    const index=jobs.findIndex(j=>j.id===action.id);check(index>=0,'Задание не найдено.');const job=jobs[index];
    if(action.action==='claim'){
      check(job.status==='queued','Задание уже не ожидает запуска.');
      check(!jobs.some(j=>j.status==='running'),'Уже выполняется другое задание.');
      check(!jobs.some(j=>j.runId===action.runId),'Идентификатор запуска уже использован.');
      jobs[index]={...job,status:'running',runId:action.runId,message:'',startedAt:now,updatedAt:now};
    }else if(action.action==='attention'){
      check(job.runId===action.runId&&(job.status==='running'||job.status==='needs_attention'),'Запуск задания не совпадает или уже завершён.');
      jobs[index]={...job,status:'needs_attention',message:action.message,updatedAt:now};
    }else if(action.action==='saved'){
      check(job.runId===action.runId&&(job.status==='running'||job.status==='needs_attention'),'Запуск задания не совпадает или уже завершён.');
      jobs[index]={...job,status:'saved',number:action.number,reference:action.reference,message:'',updatedAt:now};
    }else{
      check(job.status==='queued','Отменить можно только задание в очереди.');jobs[index]={...job,status:'cancelled',updatedAt:now};
    }
  }
  return {revision:workspace.revision+1,jobs};
}

