'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {Download,Monitor,RefreshCw,ArrowRight,FileText} from 'lucide-react';
import {money,type Partner} from './logic';
import {qtyText,type TradeDoc} from './trade';
import type {OneCJobsWorkspace,OneCJobStatus} from './onec-jobs';
type Companion={installed:boolean;configured:boolean;autoSave:boolean;paused?:boolean;mode?:string};
const labels:Record<OneCJobStatus,string>={queued:'Ожидает запуска',running:'Исполнитель работает',needs_attention:'Требуется проверка',saved:'Записан в 1С',cancelled:'Отменено'};
function askCompanion(action:'status'|'run',jobId?:string):Promise<Companion>{return new Promise((resolve,reject)=>{
 const requestId=crypto.randomUUID(),timer=setTimeout(()=>{window.removeEventListener('message',receive);reject(Error(action==='status'?'Исполнитель не найден в этом браузере.':'Ответ не получен. Обновите очередь и проверьте 1С; автоматического повтора не будет.'));},action==='status'?2000:60000);
