export type OneCEnvironment = {
  ONEC_ODATA_URL?: string; ONEC_ALLOWED_ORIGIN?: string; ONEC_OWNER_ID?: string;
  ONEC_USERNAME?: string; ONEC_PASSWORD?: string; ONEC_BEARER_TOKEN?: string;
};
export type OneCStatus = {state:'not_configured'|'configuration_error'|'configured'|'metadata_available'|'auth_required'|'unavailable';message:string;canWrite:false;entities?:string[]};
const result=(state:OneCStatus['state'],message:string):OneCStatus=>({state,message,canWrite:false});
export function oneCConfiguration(env:OneCEnvironment,owner:string):OneCStatus {
  if(!env.ONEC_OWNER_ID||env.ONEC_OWNER_ID!==owner||!env.ONEC_ODATA_URL)return result('not_configured','1С не подключена. Нужен защищённый серверный шлюз к HTTP-базе и настройка обмена.');
  try{
    const url=new URL(env.ONEC_ODATA_URL),allowed=new URL(env.ONEC_ALLOWED_ORIGIN||'');
    if(url.protocol!=='https:'||url.origin!==allowed.origin||allowed.pathname!=='/'||allowed.search||allowed.hash||allowed.username||allowed.password||url.username||url.password||url.search||url.hash||!url.pathname.endsWith('/odata/standard.odata/'))throw new Error();
    if((env.ONEC_USERNAME&&!env.ONEC_PASSWORD)||(!env.ONEC_USERNAME&&env.ONEC_PASSWORD)||(env.ONEC_BEARER_TOKEN&&(env.ONEC_USERNAME||env.ONEC_PASSWORD)))throw new Error();
    return result('configured','Адрес настроен. Проверка метаданных ещё не выполнена; создание документов в 1С недоступно.');
  }catch{return result('configuration_error','Проверьте серверную настройку HTTPS-адреса OData, разрешённого origin и способа авторизации.');}
}
export async function probeOneC(env:OneCEnvironment,owner:string,fetcher:typeof fetch=fetch):Promise<OneCStatus>{
  const status=oneCConfiguration(env,owner);if(status.state!=='configured')return status;
  const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);
  try{
    const headers:Record<string,string>={Accept:'application/xml'};
    if(env.ONEC_BEARER_TOKEN)headers.Authorization='Bearer '+env.ONEC_BEARER_TOKEN;
    else if(env.ONEC_USERNAME&&env.ONEC_PASSWORD){const bytes=new TextEncoder().encode(env.ONEC_USERNAME+':'+env.ONEC_PASSWORD);headers.Authorization='Basic '+btoa(Array.from(bytes,b=>String.fromCharCode(b)).join(''));}
    const response=await fetcher(env.ONEC_ODATA_URL+'$metadata',{method:'GET',headers,redirect:'error',signal:controller.signal,cache:'no-store'});
    if(response.status===401||response.status===403)return result('auth_required','Сервис запросил авторизацию или права на чтение метаданных. Проверьте отдельного пользователя обмена.');
    if(!response.ok||!response.body)return result('unavailable','Сервис метаданных не ответил успешно. Проверьте публикацию OData на сервере 1С.');
    const reader=response.body.getReader(),decoder=new TextDecoder();let text='',size=0;
    try{while(true){const chunk=await reader.read();if(chunk.done)break;size+=chunk.value.byteLength;if(size>2_000_000){await reader.cancel();return result('unavailable','Метаданные превышают допустимый размер проверки. Требуется настройка состава обмена.');}text+=decoder.decode(chunk.value,{stream:true});}text+=decoder.decode();}finally{reader.releaseLock();}
    if(!/<(?:\w+:)?Edmx\b/.test(text)||!/<(?:\w+:)?EntityContainer\b/.test(text))return result('unavailable','Вместо OData-метаданных получен другой ответ. Открытие веб-клиента не означает готовность обмена.');
    const entities=[...new Set(Array.from(text.matchAll(/<(?:\w+:)?EntitySet\b[^>]*\bName=["']([^"']{1,180})["']/g),m=>m[1]))].slice(0,200);
    return {...result('metadata_available','Метаданные прочитаны. Далее нужны сопоставление номенклатуры, покупателя, организации и ответственного, а также проверка формата счёта. Запись в 1С ещё не включена.'),entities};
  }catch{return result('unavailable','Не удалось прочитать метаданные. Проверьте доступность защищённого шлюза, сертификат и публикацию OData.');}
  finally{clearTimeout(timeout);}
}

