 if(!/\.xlsx$/i.test(file.name))throw Error('Выберите XLSX, CSV или TSV. Старый XLS сохраните как XLSX.');
 let total=0;const zip=unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:f=>{if(!/^xl\/(sharedStrings\.xml|worksheets\/sheet\d+\.xml)$/.test(f.name))return false;total+=f.originalSize;if(total>15_000_000||f.originalSize>8_000_000)throw Error('Распакованный прайс слишком большой.');return true;}});
 const xml=(s:string)=>{const doc=new DOMParser().parseFromString(s,'application/xml');if(doc.querySelector('parsererror'))throw Error('Повреждённый XML в Excel.');return doc;};
 const sheets=Object.keys(zip).filter(k=>k.startsWith('xl/worksheets/')).sort();if(sheets.length!==1)throw Error('Для загрузки оставьте в XLSX один лист с прайсом.');
