 const doc=xml(strFromU8(zip[sheets[0]])),rows=Array.from(doc.getElementsByTagName('row'));if(rows.length>5001)throw Error('Максимум 5000 товаров и строка заголовков.');
 return rows.map(row=>{const cells:string[]=[];for(const cell of Array.from(row.getElementsByTagName('c'))){if(cell.getElementsByTagName('f').length)throw Error('В прайсе есть формулы. Скопируйте их результаты и вставьте как значения перед загрузкой.');const ref=cell.getAttribute('r')||'',letters=ref.match(/^[A-Z]+/)?.[0];if(!letters)throw Error('Не удалось прочитать адрес ячейки.');let col=0;for(const c of letters)col=col*26+c.charCodeAt(0)-64;if(col>30)throw Error('Максимум 30 колонок. Удалите лишние столбцы.');const raw=cell.getElementsByTagName('v')[0]?.textContent||'';const type=cell.getAttribute('t');cells[col-1]=type==='s'?shared[Number(raw)]||'':type==='inlineStr'?Array.from(cell.getElementsByTagName('t'),t=>t.textContent||'').join(''):raw;}return Array.from({length:cells.length},(_,i)=>'"'+(cells[i]||'').replaceAll('"','""')+'"').join('\t');}).join('\n');
}

