export type ImportedRequestLine={name:string;qty:number;unit:string;sourcePrice:number;article:string;packagingNote:string};
// Paste exported spreadsheet rows. Supplier prices are intentionally never inferred from competitor prices.
export function parseRequestRows(text:string):ImportedRequestLine[]{
 const rows=text.trim().split(/\r?\n/).filter(s=>s.trim());
 if(!rows.length||rows.length>50)throw Error('Вставьте от 1 до 50 строк.');
 return rows.map((row,i)=>{const [name='',quantity='',unit='шт',price='0',article='',packagingNote='']=row.split('\t').map(s=>s.trim());
  const qty=Number(quantity.replaceAll(' ','')),normalized=price.replaceAll(' ','').replaceAll('\u00a0','').replace(',','.');
  if(name.length<2||name.length>180||!Number.isSafeInteger(qty)||qty<1||qty>1000000||!/^\d+(\.\d{1,2})?$/.test(normalized)||!unit||unit.length>30)throw Error('Проверьте строку '+(i+1)+': наименование, целое количество, единицу и цену с двумя знаками.');
  const [whole,fraction='']=normalized.split('.'),sourcePrice=Number(whole)*100+Number(fraction.padEnd(2,'0'));
  if(!Number.isSafeInteger(sourcePrice)||sourcePrice>100000000000||packagingNote.length>200)throw Error('Слишком большое значение в строке '+(i+1));
  return {name,qty,unit,sourcePrice,article,packagingNote};
 });
}

