const amount=z.number().int().min(0).max(100000000000);
export function isSupplierProductUrl(value:string){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&u.hostname.includes('.');}catch{return false;}}
export const requestLineSchema=z.object({id:uuid,item:ref,supplier:ref.default(''),priceBatchId:ref.default(''),priceBatchVersion:z.number().int().min(0).default(0),priceRowId:ref.default(''),supplierItemName:z.string().trim().max(180).default(''),name:z.string().trim().min(2).max(180),unit:z.string().trim().min(1).max(30),qty:z.number().int().min(1).max(1000000),buyPrice:amount,sourcePrice:amount.default(0),packagingNote:z.string().trim().max(200).default(''),availability:z.enum(['unknown','available','unavailable']).default('unknown'),sourceUrl:z.string().trim().max(1500).refine(v=>!v||isSupplierProductUrl(v)),checkedOn:optionalDay}).strict();
export const requestInputSchema=z.object({id:uuid,version:z.number().int().min(0).max(Number.MAX_SAFE_INTEGER-1),title:z.string().trim().min(3).max(160),partner:ref,supplier:ref,organization:uuid,warehouse:uuid,assignee:ref,responsible:z.literal('Михаил Булыгин').default('Михаил Булыгин'),date:day,due:optionalDay,sourceText:z.string().trim().max(6000),note:z.string().trim().max(2000),markupBps:z.number().int().min(0).max(100000).default(2000),delivery:amount,priceConfirmed:z.boolean(),deliveryConfirmed:z.boolean(),lines:z.array(requestLineSchema).min(1).max(50)}).strict();
