export type SalesRequestLine=z.infer<typeof requestLineSchema>;
export type SalesRequestInput=z.infer<typeof requestInputSchema>;
export type SalesRequest=SalesRequestInput&{state:'draft'|'approved'|'documents';created:string;updated:string;approvedAt:string;generated:{customerOrder:string;supplierOrder:string;supplierOrders?:string[];invoice:string}|null};
export type RequestReferences={partners:Partner[];catalogs:Catalog[];members:SalesMember[];priceBatches?:SupplierPriceReference[]};
export type SupplierPriceReference={id:string;version:number;supplier:string;active:boolean;rows:{id:string;name:string;unit:string;price:number}[]};
export const lineSupplier=(line:SalesRequestLine,request:Pick<SalesRequestInput,'supplier'>)=>line.supplier||request.supplier;
export class RequestError extends Error {}
const check=(ok:unknown,message:string)=>{if(!ok)throw new RequestError(message);};
const cap=BigInt(100000000000);
const bounded=(v:bigint)=>{check(v>=BigInt(0)&&v<=cap,'Сумма заявки превышает допустимый предел.');return Number(v);};
export function calculateRequest(input:Pick<SalesRequestInput,'lines'|'delivery'|'markupBps'>){
  check(input.lines.length>0&&input.lines.length<=50,'Добавьте от 1 до 50 строк.');
  check(Number.isSafeInteger(input.delivery)&&input.delivery>=0&&input.delivery<=Number(cap),'Проверьте стоимость доставки.');
  check(Number.isSafeInteger(input.markupBps)&&input.markupBps>=0&&input.markupBps<=100000,'Проверьте наценку.');
