import { z } from 'zod';

export const taskKinds = {call:'Звонок',quote:'Предложение',invoice:'Счёт',shipment:'Отгрузка',payment:'Оплата',other:'Другое'} as const;
export const taskStatuses = {todo:'К выполнению',doing:'В работе',review:'На проверке',done:'Готово',cancelled:'Отменено'} as const;
export type SalesMember = {id:string;name:string;role:'lead'|'assistant';active:boolean};
export type SalesClient = {partner:string;assistant:string;priority:'normal'|'important';nextContact:string;note:string};
export type SalesTask = {id:string;title:string;partner:string;document:string;assignee:string;kind:keyof typeof taskKinds;due:string;status:keyof typeof taskStatuses;priority:'normal'|'high';note:string;result:string;created:string;updated:string};
export type SalesHistory = {id:string;at:string;message:string};
export type SalesWorkspace = {members:SalesMember[];clients:SalesClient[];tasks:SalesTask[];history:SalesHistory[];revision:number};
export type SalesReferences = {partners:{id:string;name:string;role:string}[];documents:{id:string;partner:string;kind:string}[]};
export class SalesError extends Error {}
const check = (ok:unknown,message:string) => {if(!ok)throw new SalesError(message);};
const uuid=z.string().uuid(),ref=z.union([uuid,z.literal('')]);
const day=z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine(v=>!isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v);
const optionalDay=z.union([day,z.literal('')]);
const revision=z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER-1);
const status=z.enum(['todo','doing','review','done','cancelled']);
export const salesActionSchema=z.discriminatedUnion('action',[
  z.object({action:z.literal('initialize')}).strict(),
  z.object({action:z.literal('member'),revision,id:uuid,name:z.string().trim().min(2).max(80),role:z.enum(['lead','assistant']),active:z.boolean()}).strict(),
  z.object({action:z.literal('client'),revision,partner:uuid,assistant:uuid,priority:z.enum(['normal','important']),nextContact:optionalDay,note:z.string().trim().max(2000)}).strict(),
  z.object({action:z.literal('task'),revision,id:uuid,title:z.string().trim().min(3).max(160),partner:ref,document:ref,assignee:uuid,kind:z.enum(['call','quote','invoice','shipment','payment','other']),due:optionalDay,status,priority:z.enum(['normal','high']),note:z.string().trim().max(2000),result:z.string().trim().max(2000)}).strict(),
  z.object({action:z.literal('task_status'),revision,id:uuid,status,result:z.string().trim().max(2000).optional()}).strict(),
]);
export type SalesAction=z.infer<typeof salesActionSchema>;
export const emptySalesWorkspace=():SalesWorkspace=>({members:[],clients:[],tasks:[],history:[],revision:0});
const openTask=(t:SalesTask)=>t.status!=='done'&&t.status!=='cancelled';
function record(w:SalesWorkspace,message:string,at:string) {
  w.history=[{id:crypto.randomUUID(),at,message},...w.history].slice(0,200);
}
async function stableId(owner:string,key:string) {
  const bytes=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(['sales-team',owner,key]))));
  bytes[6]=(bytes[6]&15)|80;bytes[8]=(bytes[8]&63)|128;
  const s=[...bytes.slice(0,16)].map(b=>b.toString(16).padStart(2,'0')).join('');
  return `${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`;
}
export async function initializeSalesWorkspace(owner:string,demo:boolean,refs:SalesReferences,now=new Date().toISOString()):Promise<SalesWorkspace> {
  const w=emptySalesWorkspace();
  w.members=await Promise.all(['Миша','Петя','Олег','Наташа','Дима'].map(async(name,i)=>({id:await stableId(owner,'member:'+i),name,role:i===0?'lead' as const:'assistant' as const,active:true})));
  if(demo) {
    const clients=refs.partners.filter(p=>p.role==='customer'||p.role==='both').slice(0,3);
    w.clients=clients.map((p,i)=>({partner:p.id,assistant:w.members[i+1].id,priority:i===0?'important':'normal',nextContact:now.slice(0,10),note:'Учебный клиент команды'}));
    const kinds=(['call','quote','invoice','shipment','payment','other'] as const);
    for(let i=0;i<(clients.length?6:0);i++) {
      const p=clients[i%clients.length],kind=kinds[i];
      const doc=refs.documents.find(d=>d.partner===p.id&&d.kind===({invoice:'invoice',shipment:'sale',payment:'receipt'} as Record<string,string>)[kind]);
      w.tasks.push({id:await stableId(owner,'task:'+i),title:`Учебная задача: ${taskKinds[kind].toLowerCase()} · ${p.name}`.slice(0,160),partner:p.id,document:doc?.id||'',assignee:w.members[1+i%4].id,kind,due:now.slice(0,10),status:i===0?'doing':i===1?'review':'todo',priority:i===0?'high':'normal',note:'Учебный пример. Действия с контрагентом не выполнялись.',result:i===1?'Учебное предложение подготовлено.':'',created:now,updated:now});
    }
  }
  record(w,demo?'Создана учебная команда Миши с примерами задач.':'Создана команда Миши: Петя, Олег, Наташа, Дима.',now);
  return w;
}
export function changeSalesWorkspace(current:SalesWorkspace,action:Exclude<SalesAction,{action:'initialize'}>,refs:SalesReferences,now=new Date().toISOString()):SalesWorkspace {
  check(action.revision===current.revision,'Данные изменились в другом окне. Обновите список.');
  check(current.members.length,'Сначала создайте команду.');
  const w=structuredClone(current);
  const activeMember=(id:string)=>w.members.find(m=>m.id===id&&m.active);
  const customer=(id:string)=>refs.partners.find(p=>p.id===id&&(p.role==='customer'||p.role==='both'));
  if(action.action==='member') {
    const old=w.members.find(m=>m.id===action.id);
    check(old?old.role===action.role:action.role==='assistant','Роль руководителя менять нельзя.');
    check(action.role!=='lead'||action.active,'Руководитель должен оставаться активным.');
    check(action.active||(!w.clients.some(c=>c.assistant===action.id)&&!w.tasks.some(t=>t.assignee===action.id&&openTask(t))),'Сначала передайте клиентов и открытые задачи другому сотруднику.');
    check(old||w.members.length<50,'В команде может быть не более 50 сотрудников.');
    const member:SalesMember={id:action.id,name:action.name,role:action.role,active:action.active};
    if(old)w.members[w.members.indexOf(old)]=member;else w.members.push(member);
    record(w,`${old?'Изменён':'Добавлен'} сотрудник: ${member.name}${member.active?'':' (неактивен)'}.`,now);
  } else if(action.action==='client') {
    check(customer(action.partner),'Покупатель недоступен в этой базе.');
    check(activeMember(action.assistant)?.role==='assistant','Выберите активного помощника.');
    const old=w.clients.find(c=>c.partner===action.partner);
    check(old||w.clients.length<500,'В портфеле может быть не более 500 клиентов.');
    const client:SalesClient={partner:action.partner,assistant:action.assistant,priority:action.priority,nextContact:action.nextContact,note:action.note};
    if(old)w.clients[w.clients.indexOf(old)]=client;else w.clients.push(client);
    record(w,`${old?'Обновлён':'Добавлен'} клиент: ${customer(action.partner)!.name}.`,now);
  } else {
    const old=w.tasks.find(t=>t.id===action.id);
    if(action.action==='task_status')check(old,'Задача не найдена.');
    check(old||w.tasks.length<1000,'В команде может быть не более 1000 задач.');
    const task:SalesTask=action.action==='task_status'
      ?{...old!,status:action.status,result:action.result??old!.result,updated:now}
      :{id:action.id,title:action.title,partner:action.partner,document:action.document,assignee:action.assignee,kind:action.kind,due:action.due,status:action.status,priority:action.priority,note:action.note,result:action.result,created:old?.created||now,updated:now};
    check(activeMember(task.assignee)||(!openTask(task)&&old?.assignee===task.assignee),'Выберите активного исполнителя.');
    check(!task.partner||(customer(task.partner)&&w.clients.some(c=>c.partner===task.partner)),'Сначала добавьте покупателя в портфель команды.');
    check(!task.document||(task.partner&&refs.documents.some(d=>d.id===task.document&&d.partner===task.partner)),'Документ недоступен или относится к другому клиенту.');
    check(task.status!=='done'||task.result.trim().length>=3,'Для завершения задачи укажите результат (минимум 3 символа).');
    if(old)w.tasks[w.tasks.indexOf(old)]=task;else w.tasks.push(task);
    record(w,`${old?'Обновлена':'Создана'} задача «${task.title}»: ${taskStatuses[task.status]}.`,now);
  }
  check(w.members.filter(m=>m.role==='lead'&&m.active).length===1,'В команде должен быть один руководитель.');
  return w;
}

