import type {Doc} from './logic';
import {remaining} from './logic';
import {fulfilled,settlements,type TradeDoc} from './trade';
export function clientSales(partner:string,documents:TradeDoc[],legacy:Doc[],today:string){
 const trade=documents.filter(d=>d.partner===partner&&d.date<=today),old=legacy.filter(d=>d.partner===partner&&d.date<=today),accounts=settlements(trade).filter(r=>r.customer);
 const oldSales=old.filter(d=>d.state==='posted'&&d.kind==='sale');
 const debt=accounts.reduce((s,r)=>s+r.debt,0)+oldSales.reduce((s,d)=>s+Math.max(0,remaining(d,old)),0);
 const overdue=accounts.filter(r=>r.doc.due&&r.doc.due<today).reduce((s,r)=>s+r.debt,0)+oldSales.filter(d=>d.due&&d.due<today).reduce((s,d)=>s+Math.max(0,remaining(d,old)),0);
 const month=today.slice(0,7),revenue=trade.filter(d=>d.state==='posted'&&d.kind==='sale'&&d.date.startsWith(month)).reduce((s,d)=>s+d.amount,0)+oldSales.filter(d=>d.date.startsWith(month)).reduce((s,d)=>s+d.amount,0);
 const orders=trade.filter(d=>d.kind==='customer_order'&&d.state==='posted'&&d.lines.some(l=>fulfilled(d,l.item,trade)<l.qty));
 const docs=trade.filter(d=>d.state!=='void'&&['customer_order','sale','invoice','receipt'].includes(d.kind)).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created));
 return {debt,overdue,revenue,orders,documents:docs};
}

