'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {Users,Plus,ArrowRight,Check,Clock,Briefcase,RefreshCw,Search,X,Pencil,CheckCheck,FileText} from 'lucide-react';
import {money,type Partner,type Doc,type Catalog} from './logic';
import {tradeKinds,type TradeDoc} from './trade';
import {taskKinds,taskStatuses,type SalesWorkspace as Team,type SalesTask,type SalesMember,type SalesClient} from './sales-team';
import RequestWorkspace from './request-workspace';
import SupplierWorkspace from './supplier-workspace';
import OneCWorkspace from './onec-workspace';
import type {SaveDirectory} from './directory-ui';
import {clientSales} from './sales-workspace-data';

type Props={catalogs:Catalog[];saveDirectory:SaveDirectory;onRefreshERP:()=>Promise<void>;dataset:string;partners:Partner[];documents:TradeDoc[];legacy:Doc[];onOpen:(doc:TradeDoc)=>void;onCreateOrder:(partner:string)=>void;onDirectory:()=>void};
type Modal={type:'member';member?:SalesMember}|{type:'client';client?:SalesClient}|{type:'task';task?:SalesTask;partner?:string;document?:string}|{type:'complete';task:SalesTask};
const finalStatus=(s:string)=>s==='done'||s==='cancelled';
const prettyDate=(s:string)=>s?s.split('-').reverse().join('.'):'Без срока';
const blankTask=(assignee:string,partner=''):Omit<SalesTask,'created'|'updated'>=>({id:crypto.randomUUID(),title:'',partner,document:'',assignee,kind:'other',due:'',status:'todo',priority:'normal',note:'',result:''});

export default function SalesWorkspace({dataset,partners,documents,legacy,onOpen,onCreateOrder,onDirectory,catalogs,saveDirectory,onRefreshERP}:Props){
 const [team,setTeam]=useState<Team|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[conflict,setConflict]=useState(false);
 const [tab,setTab]=useState('today'),[person,setPerson]=useState('all'),[status,setStatus]=useState('open'),[query,setQuery]=useState(''),[clientFocus,setClientFocus]=useState(''),[modal,setModal]=useState<Modal|null>(null);
 const generation=useRef(0),today=new Date().toLocaleDateString('sv-SE'),dialog=useRef<HTMLDialogElement>(null);
 const request=useCallback(async(initialize=false,signal?:AbortSignal)=>{const response=await fetch('/api/sales-team?dataset='+dataset,initialize?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'initialize'}),signal}:{cache:'no-store',signal});const body=await response.json() as Team&{error?:string};if(!response.ok)throw Error(body.error||'Не удалось загрузить рабочее место.');return body;},[dataset]);
 async function load(initialize=false){if(busy)return;const g=++generation.current;setLoading(true);setError('');try{const body=await request(initialize);if(g===generation.current){setTeam(body);setConflict(false);}}catch(e){if(g===generation.current)setError(e instanceof Error?e.message:'Ошибка загрузки.');}finally{if(g===generation.current)setLoading(false);}}
 useEffect(()=>{const controller=new AbortController();request(true,controller.signal).then(body=>{if(!controller.signal.aborted)setTeam(body);}).catch(e=>{if(!controller.signal.aborted)setError(e instanceof Error?e.message:'Ошибка загрузки.');}).finally(()=>{if(!controller.signal.aborted)setLoading(false);});return()=>controller.abort();},[request]);
 useEffect(()=>{if(modal)dialog.current?.showModal();else dialog.current?.close();},[modal]);
 useEffect(()=>{if(notice){const id=setTimeout(()=>setNotice(''),4000);return()=>clearTimeout(id);}},[notice]);
 async function save(payload:Record<string,unknown>){if(!team||busy||loading)return;setBusy(true);setConflict(false);setError('');try{const r=await fetch('/api/sales-team?dataset='+dataset,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,revision:team.revision})}),b=await r.json() as Team&{error?:string};if(!r.ok){setConflict(r.status===409);throw Error(b.error||'Не удалось сохранить.');}setTeam(b);setModal(null);setNotice('Сохранено в рабочем пространстве');}catch(e){setError(e instanceof Error?e.message:'Ошибка сохранения.');}finally{setBusy(false);}}
 const partnerName=(id:string)=>partners.find(p=>p.id===id)?.name||'Без клиента',memberName=(id:string)=>team?.members.find(m=>m.id===id)?.name||'Не назначен';
 const lead=team?.members.find(m=>m.role==='lead'),openTasks=team?.tasks.filter(t=>!finalStatus(t.status))||[],members=team?.members.filter(m=>m.active)||[];
 const metrics=team?.clients.map(c=>({client:c,...clientSales(c.partner,documents,legacy,today)}))||[];
 const totals=metrics.reduce((a,c)=>({debt:a.debt+c.debt,overdue:a.overdue+c.overdue,revenue:a.revenue+c.revenue,orders:a.orders+c.orders.length}),{debt:0,overdue:0,revenue:0,orders:0});
 const taskRows=(team?.tasks||[]).filter(t=>(person==='all'||t.assignee===person)&&(status==='all'||(status==='open'?!finalStatus(t.status):t.status===status))&&(!clientFocus||t.partner===clientFocus)&&`${t.title} ${partnerName(t.partner)} ${memberName(t.assignee)}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')||Number(b.priority==='high')-Number(a.priority==='high'));
 const dueTasks=openTasks.filter(t=>t.due&&t.due<=today).sort((a,b)=>a.due.localeCompare(b.due));
 const review=openTasks.filter(t=>t.status==='review');
 const editTask=(task?:SalesTask,partner='',document='')=>{setError('');setModal({type:'task',task,partner,document});};
 function taskCard(t:SalesTask){return <article key={t.id} className={'misha-task '+(t.due&&t.due<today&&!finalStatus(t.status)?'late':'')}><div className="misha-task-meta"><span className={'team-status '+t.status}>{taskStatuses[t.status]}</span>{t.priority==='high'&&<span className="team-priority">Важно</span>}<span>{taskKinds[t.kind]}</span></div><button className="misha-task-title" onClick={()=>editTask(t)}>{t.title}</button><p>{partnerName(t.partner)}</p><div className="misha-task-person"><span className="team-avatar">{memberName(t.assignee).slice(0,1)}</span><b>{memberName(t.assignee)}</b><span className={t.due&&t.due<today&&!finalStatus(t.status)?'overdue':''}><Clock size={13}/>{prettyDate(t.due)}</span></div>{t.document&&<button className="misha-doc-link" onClick={()=>{const d=documents.find(d=>d.id===t.document);if(d)onOpen(d);}}><FileText size={13}/>{documents.find(d=>d.id===t.document)?.number||'Документ'}</button>}{t.result&&<p className="misha-result">Результат: {t.result}</p>}<div className="misha-task-actions">{t.status==='todo'&&<button disabled={busy} onClick={()=>save({action:'task_status',id:t.id,status:'doing'})}>В работу <ArrowRight size={13}/></button>}{t.status==='doing'&&<button disabled={busy} onClick={()=>save({action:'task_status',id:t.id,status:'review'})}>На проверку <CheckCheck size={13}/></button>}{!finalStatus(t.status)&&<button disabled={busy} onClick={()=>{setError('');setModal({type:'complete',task:t});}}>{t.status==='review'?'Принять работу':'Завершить'} <Check size={13}/></button>}<button disabled={busy} onClick={()=>editTask(t)} aria-label={'Изменить задачу '+t.title}><Pencil size={13}/></button></div></article>;}
 if(loading&&!team)return <div className="loading" role="status">Готовим рабочее пространство Миши…</div>;
 if(!team)return <div className="error" role="alert">{error}<button onClick={()=>load(true)}>Повторить</button></div>;
 return <div className="misha-workspace">
  <section className="misha-banner"><span className="misha-avatar">М</span><div><span className="eyebrow">ПРОДАЖИ И СОПРОВОЖДЕНИЕ КЛИЕНТОВ</span><h2>{lead?.name||'Миша'} и команда</h2><p>{members.filter(m=>m.role==='assistant').map(m=>m.name).join(' · ')||'Добавьте помощников для распределения работы'}</p></div><button className="primary" disabled={busy} onClick={()=>editTask()}><Plus size={16}/>Поручение</button><button className="secondary" disabled={busy||loading} aria-label="Обновить рабочее место" onClick={()=>load()}><RefreshCw size={16}/></button></section>
  <div className="misha-kpis"><article><span>Клиентов в работе</span><strong>{team.clients.length}</strong><small>{totals.orders} активных заказов</small></article><article><span>Продажи за {new Date(today+'T12:00:00').toLocaleDateString('ru-RU',{month:'long'})}</span><strong>{money(totals.revenue)}</strong><small>По проведённым отгрузкам</small></article><article><span>Долг клиентов</span><strong>{money(totals.debt)}</strong><small className={totals.overdue?'overdue':''}>Просрочено {money(totals.overdue)}</small></article><article><span>Открытых поручений</span><strong>{openTasks.length}</strong><small>{dueTasks.length} со сроком сегодня или раньше</small></article></div>
  <div className="misha-tabs">{[['today','Рабочий день'],['requests','Заявки → счёт'],['suppliers','Поставщики и прайсы'],['onec','Подключение 1С'],['clients','Мои клиенты'],['tasks','Поручения'],['team','Команда']].map(([key,label])=><button key={key} className={tab===key?'selected':''} onClick={()=>{setTab(key);setClientFocus('');setQuery('');}}>{label}{key==='tasks'&&<span>{openTasks.length}</span>}{key==='team'&&<span>{members.length}</span>}</button>)}</div>
  {error&&!modal&&<div className="error" role="alert">{error} <button onClick={()=>load()}>Обновить данные</button></div>}
  {tab==='requests'&&<RequestWorkspace dataset={dataset} partners={partners} catalogs={catalogs} documents={documents} members={team.members} saveDirectory={saveDirectory} onRefreshERP={onRefreshERP} onOpen={onOpen}/>}
  {tab==='suppliers'&&<SupplierWorkspace key={dataset} dataset={dataset} partners={partners} catalogs={catalogs} saveDirectory={saveDirectory}/>}
  {tab==='onec'&&<OneCWorkspace key={dataset} dataset={dataset} documents={documents} partners={partners} onOpen={onOpen}/>}
  {tab==='today'&&<><div className="misha-day-grid"><section className="panel misha-section"><div className="misha-section-title"><div><h2>Сроки сегодня и просрочки</h2><p>Поручения, которые требуют внимания</p></div><span className="misha-count">{dueTasks.length}</span></div>{dueTasks.length?<div className="misha-task-grid">{dueTasks.slice(0,6).map(taskCard)}</div>:<div className="misha-empty"><CheckCheck size={28}/><h3>Срочных поручений нет</h3><p>Поставьте задачу помощнику и укажите срок.</p></div>}{dueTasks.length>6&&<button className="text-button" onClick={()=>setTab('tasks')}>Все поручения <ArrowRight size={14}/></button>}</section><section className="panel misha-section"><div className="misha-section-title"><div><h2>Мише на проверку</h2><p>Результаты работы помощников</p></div><span className="misha-count">{review.length}</span></div>{review.length?<div className="misha-review-list">{review.slice(0,5).map(taskCard)}</div>:<div className="misha-empty"><Briefcase size={28}/><h3>Очередь проверки пуста</h3><p>Переведите поручение в статус «На проверке», когда помощник закончит работу.</p></div>}</section></div><section className="panel misha-section"><div className="misha-section-title"><div><h2>Ближайшие контакты с клиентами</h2><p>Запланированные звонки и следующие шаги</p></div><button className="text-button" onClick={()=>setTab('clients')}>Мои клиенты <ArrowRight size={14}/></button></div>{team.clients.some(c=>c.nextContact)?<div className="misha-contact-list">{team.clients.filter(c=>c.nextContact).sort((a,b)=>a.nextContact.localeCompare(b.nextContact)).slice(0,6).map(c=><button key={c.partner} onClick={()=>{setError('');setModal({type:'client',client:c});}}><span className={c.nextContact<today?'overdue':''}>{prettyDate(c.nextContact)}</span><strong>{partnerName(c.partner)}<small>{memberName(c.assistant)}</small></strong><ArrowRight size={15}/></button>)}</div>:<div className="misha-empty small"><p>Выберите клиентов и назначьте дату следующего контакта.</p><button className="secondary" onClick={()=>{setError('');setModal({type:'client'});}}>Закрепить клиента</button></div>}</section></>}
