th={2000} value={task.note} onChange={e=>setTask({...task,note:e.target.value})}/></label><label>Результат выполнения<textarea rows={2} required={task.status==='done'} minLength={task.status==='done'?3:undefined} maxLength={2000} value={task.result} onChange={e=>setTask({...task,result:e.target.value})} placeholder="Что сделано, договорённости или причина отмены"/></label></>}
