export const supplierImportSchema=z.object({action:z.literal('import'),id:z.string().uuid(),version:z.number().int().nonnegative(),supplier:z.string().uuid(),name:z.string().trim().min(2).max(150),validOn:date,rows:z.array(supplierPriceRowSchema).min(1).max(5000)}).strict().refine(b=>new Set(b.rows.map(r=>r.id)).size===b.rows.length,{message:'Повторяющиеся идентификаторы строк'});
export const supplierDisableSchema=z.object({action:z.literal('disable'),id:z.string().uuid(),version:z.number().int().positive()}).strict();
export const supplierActionSchema=z.union([supplierImportSchema,supplierDisableSchema]);
export type SupplierPriceRow=z.infer<typeof supplierPriceRowSchema>;
export type SupplierPriceBatch=Omit<z.infer<typeof supplierImportSchema>,'action'>&{active:boolean;created:string;updated:string};
export function normalizeSupplierText(s:string){return s.toLowerCase().replace(/ё/g,'е').replace(/(\d)\s*[×хx]\s*(?=\d)/g,'$1x').replace(/[^\p{L}\p{N}]+/gu,' ').trim().replace(/\s+/g,' ');}
const normalizeUnit=(s:string)=>s.toLowerCase().replace(/[.\s]/g,'').replace(/^штук[аи]?$/,'шт').replace(/^метр[аы]?$/,'м');
const synonym:Record<string,string>={'перчатки':'перчатка','перчаток':'перчатка','саморезы':'саморез','шуруп':'саморез','шурупы':'саморез','ведра':'ведро','оцинкованное':'оцинк','оцинкованный':'оцинк','оцинкованная':'оцинк','оцинкованные':'оцинк','мешки':'мешок','валик':'валик','валики':'валик','бетону':'бетон','бетона':'бетон','электрический':'электро','электрическая':'электро'};
