 const n=normalizeSupplierText(query.name),a=normalizeSupplierText(query.article||''),q=new Set(tokens(query.name)),dims=dimensions(query.name);if(!n&&!a)return [];
 const result:SupplierPriceMatch[]=[];
 for(const b of batches.filter(b=>b.active))for(const row of b.rows){
  const rowArticle=normalizeSupplierText(row.article),articleInName=!!rowArticle&&(' '+n+' ').includes(' '+rowArticle+' '),exactArticle=!!rowArticle&&(a?a===rowArticle:articleInName),exactName=!!n&&n===normalizeSupplierText(row.name),rt=new Set(tokens(row.name));
