  const rd=dimensions(row.name),queryDims=exactArticle&&articleInName?dimensions((' '+n+' ').replace(' '+rowArticle+' ',' ')):dims;if(queryDims.length&&(!queryDims.every(v=>rd.includes(v))||rd.some(v=>!queryDims.includes(v))))conflicts.push('Числа, размеры или модель отличаются — аналог требует проверки');
