  <div className="list-toolbar trade-toolbar"><label className="search"><Search size={17}/><input aria-label="Поиск торговых документов" placeholder={tab==='balances'?'Товар или склад':'Номер, контрагент, примечание'} value={query} onChange={e=>setQuery(e.target.value)}/></label><select aria-label="Фильтр по организации" value={organization} onChange={e=>setOrganization(e.target.value)}><option value="">Все организации</option>{catalogs.filter(c=>c.kind==='organization').map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>{view==='stock'?<select aria-label="Фильтр по складу" value={warehouse} onChange={e=>setWarehouse(e.target.value)}><option value="">Все склады</option>{catalogs.filter(c=>c.kind==='warehouse').map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select>:null}{!['balances','settlements'].includes(tab)&&<select aria-label="Статус торгового документа" value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Все статусы</option>{Object.entries(statuses).map(([s,l])=><option key={s} value={s}>{l}</option>)}</select>}
  <button className="secondary" onClick={()=>csvDownload('atlas-'+tab,tab==='balances'?[['Организация','Склад','Товар','Ед.','Количество','Стоимость, руб.'],...stocks.map(r=>[catalogName(r.organization),catalogName(r.warehouse),r.name,r.unit,r.qty/1000,r.value/100])]:tab==='settlements'?[['Контрагент','Документ','Начислено','Оплачено','Долг','Аванс'],...ledger.map(r=>[name(r.doc.partner),r.doc.number,r.realized/100,r.paid/100,r.debt/100,r.advance/100])]:[['Документ','Номер','Дата','Контрагент','Сумма, руб.','Статус'],...rows.map(d=>[tradeKinds[d.kind],d.number,d.date,name(d.partner),d.amount/100,statuses[d.state]])])}><Download size={16}/>CSV</button><button className="primary" onClick={()=>start(primaryKind)}><Plus size={17}/>{tab==='balances'?'Ввести остатки':tab==='settlements'?'Получить оплату':'Создать'}</button></div>
  {tab==='balances'?<><div className="table-wrap"><table><thead><tr><th>Товар / организация</th><th>Склад</th><th>В наличии</th><th>Средняя стоимость</th><th>Стоимость запаса</th></tr></thead><tbody>{stocks.map(r=><tr key={[r.organization,r.warehouse,r.item].join(':')}><td>{r.name}<small className="cell-sub">{catalogName(r.organization)}</small></td><td>{catalogName(r.warehouse)}</td><td className="numeric">{qtyText(r.qty)} {r.unit}</td><td>{money(r.qty?Math.round(r.value*1000/r.qty):0)}</td><td className="numeric">{money(r.value)}</td></tr>)}</tbody></table>{!stocks.length&&<div className="empty"><Package size={28}/><h3>Нет складских остатков</h3><p>Проведите приходную накладную или введите начальные остатки.</p></div>}</div><div className="table-bottom">Остатки по всем проведённым товарным документам. Заказы не резервируют запас. Прежние документы без количества на склад не влияют.</div></>:tab==='settlements'?<><div className="table-wrap"><table><thead><tr><th>Контрагент / основание</th><th>Срок оплаты</th><th>Поставлено / начислено</th><th>Оплачено</th><th>Долг</th><th>Аванс</th></tr></thead><tbody>{ledger.map(r=><tr key={r.doc.id} onClick={()=>details(r.doc)}><td><button className="doc-link" onClick={()=>details(r.doc)}><span>{name(r.doc.partner)}<small>{tradeKinds[r.doc.kind]} № {r.doc.number}</small></span></button></td><td className={r.doc.due&&r.doc.due<today()&&r.debt>0?'overdue':''}>{r.doc.due||'—'}</td><td>{money(r.realized)}</td><td>{money(r.paid)}</td><td className="numeric">{money(r.debt)}</td><td>{money(r.advance)}</td></tr>)}</tbody></table>{!ledger.length&&<div className="empty"><h3>Взаиморасчётов пока нет</h3></div>}</div><div className="table-bottom">Долг возникает после поставки или начисления расхода. Оплата до поставки отражается как аванс.</div></>:<>{docTable(rows)}<div className="table-bottom">{rows.length} документов · все даты · суммы в рублях · только проведённые документы влияют на учёт</div></>}
  </section>
