   <div className="form-grid"><label>Вид документа<select value={edit.kind} disabled={!!edit.version} onChange={e=>start(e.target.value as TradeKind)}>{Object.entries(tradeKinds).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Номер<input placeholder="Присвоится автоматически" maxLength={60} value={edit.number} onChange={e=>setEdit({...edit,number:e.target.value})}/></label><label>Дата<input type="date" required value={edit.date} onChange={e=>setEdit({...edit,date:e.target.value})}/></label><label>Срок поставки / оплаты<input type="date" value={edit.due} onChange={e=>setEdit({...edit,due:e.target.value})}/></label></div>
