    {(stockKinds.includes(edit.kind)||['customer_order','supplier_order'].includes(edit.kind))&&<ReferenceField label={edit.kind==='transfer'?'Склад отправления':'Склад'} kind="warehouse" value={edit.warehouse} onChange={id=>setEdit({...edit,warehouse:id,target:edit.target===id?'':edit.target})} catalogs={catalogs} partners={partners} save={saveDirectory}/>}
