  {docs.some(d=>d.basis===picked.id)&&<section className="related-docs"><h3>Связанные документы</h3>{docs.filter(d=>d.basis===picked.id).map(d=><button key={d.id} onClick={()=>details(d)}><FileText size={16}/><span>{tradeKinds[d.kind]} № {d.number}</span><span className={'badge '+d.state}>{statuses[d.state]}</span><ArrowRight size={15}/></button>)}</section>}
