import type { Catalog, Partner } from './logic';

export const tradeKinds = {
  customer_order: 'Заказ покупателя', supplier_order: 'Заказ поставщику', invoice: 'Счёт покупателю',
  sale: 'Расходная накладная', purchase: 'Приходная накладная', receipt: 'Поступление денег',
  payment: 'Оплата поставщику', expense: 'Расход', transfer: 'Перемещение', stock_in: 'Оприходование', stock_out: 'Списание',
} as const;
export type TradeKind = keyof typeof tradeKinds;
export type TradeLine = { item: string; name: string; unit: string; type: string; qty: number; price: number; amount: number; cost: number };
export type TradeDoc = {
  id: string; kind: TradeKind; number: string; date: string; due: string; partner: string;
  organization: string; warehouse: string; target: string; basis: string; note: string;
  amount: number; cost: number; channel: string; state: 'draft'|'posted'|'void';
  lines: TradeLine[]; version: number; sequence: number; reason: string; created: string;
};
export type TradeInput = Omit<TradeDoc, 'state'|'cost'|'sequence'|'reason'|'created'|'lines'> & { lines: {item:string;qty:number;price:number}[] };
export type StockRow = { organization:string; warehouse:string; item:string; name:string; unit:string; qty:number; value:number; date:string; sequence:number };
export const orderKinds: TradeKind[] = ['customer_order','supplier_order'];
export const moneyKinds: TradeKind[] = ['receipt','payment'];
export const stockKinds: TradeKind[] = ['sale','purchase','stock_in','stock_out','transfer'];
export const stockOnly: TradeKind[] = ['stock_in','stock_out','transfer'];
export const isOrder = (d:TradeDoc) => orderKinds.includes(d.kind);
export const qtyText = (q:number) => new Intl.NumberFormat('ru-RU',{maximumFractionDigits:3}).format(q/1000);
export class TradeError extends Error {}
const check = (condition:unknown, message:string) => { if(!condition) throw new TradeError(message); };
const key = (o:string,w:string,i:string) => [o,w,i].join('|');
export const lineAmount = (qty:number,price:number) => Number((BigInt(qty)*BigInt(price)+BigInt(500))/BigInt(1000));
const today = () => new Date().toISOString().slice(0,10);
const finiteAmount = (n:number) => Number.isSafeInteger(n)&&n>=0&&n<=100000000000;

export function stockRows(docs:TradeDoc[]):StockRow[] {
  const map = new Map<string,StockRow>();
  for(const d of docs.filter(d=>d.state==='posted'&&stockKinds.includes(d.kind)).sort((a,b)=>a.sequence-b.sequence)) {
    for(const l of d.lines.filter(l=>l.type!=='service')) {
      const incoming=['purchase','stock_in'].includes(d.kind);
      const apply=(w:string,q:number,v:number)=>{
        const k=key(d.organization,w,l.item), r=map.get(k)||{organization:d.organization,warehouse:w,item:l.item,name:l.name,unit:l.unit,qty:0,value:0,date:'',sequence:0};
        r.qty+=q;r.value+=v;r.date=d.date;r.sequence=d.sequence;map.set(k,r);
      };
      apply(d.warehouse,incoming?l.qty:-l.qty,incoming?l.amount:-l.cost);
      if(d.kind==='transfer')apply(d.target,l.qty,l.cost);
    }
  }
  return [...map.values()];
}
export function fulfilled(order:TradeDoc,item:string,docs:TradeDoc[]) {
  return docs.filter(d=>d.state==='posted'&&d.basis===order.id&&d.kind===(order.kind==='customer_order'?'sale':'purchase')).reduce((sum,d)=>sum+d.lines.filter(l=>l.item===item).reduce((s,l)=>s+l.qty,0),0);
}
export function fulfillment(order:TradeDoc,docs:TradeDoc[]) {
  const total=order.lines.reduce((s,l)=>s+l.qty,0),done=order.lines.reduce((s,l)=>s+fulfilled(order,l.item,docs),0);
  return {total,done,percent:total?Math.min(100,Math.round(done/total*100)):0,label:done===0?'Не исполнен':done>=total?'Исполнен':'Частично исполнен'};
}
export function paymentRoot(d:TradeDoc,docs:TradeDoc[]):TradeDoc {
  if(d.basis&&['sale','purchase','invoice','receipt','payment'].includes(d.kind))return docs.find(p=>p.id===d.basis)||d;
  return d;
}
export function paid(d:TradeDoc,docs:TradeDoc[]) {
  const root=paymentRoot(d,docs);
  return docs.filter(p=>p.state==='posted'&&moneyKinds.includes(p.kind)&&p.basis===root.id).reduce((s,p)=>s+p.amount,0);
}
export function toPay(d:TradeDoc,docs:TradeDoc[]) {const root=paymentRoot(d,docs);return Math.max(0,root.amount-paid(root,docs));}
export function settlements(docs:TradeDoc[]) {
  const roots=docs.filter(d=>d.state==='posted'&&(isOrder(d)||(['sale','purchase','expense'].includes(d.kind)&&!d.basis)));
  return roots.map(d=>{
    const realized=isOrder(d)?docs.filter(c=>c.state==='posted'&&c.basis===d.id&&['sale','purchase'].includes(c.kind)).reduce((s,c)=>s+c.amount,0):d.amount;
    const payment=paid(d,docs);return {doc:d,realized,paid:payment,debt:Math.max(0,realized-payment),advance:Math.max(0,payment-realized),planned:Math.max(0,d.amount-payment),customer:['customer_order','sale'].includes(d.kind)};
  });
}
export function tradeReport(docs:TradeDoc[],month:string) {
  const list=docs.filter(d=>d.state==='posted'&&d.date.startsWith(month));
  const sum=(kind:TradeKind,field:'amount'|'cost'='amount')=>list.filter(d=>d.kind===kind).reduce((s,d)=>s+d[field],0);
  const revenue=sum('sale'),cost=sum('sale','cost'),expense=sum('expense')+sum('stock_out','cost');
  return {revenue,cost,expense,profit:revenue-cost-expense,incoming:sum('receipt'),outgoing:sum('payment')};
}

export function makeDraft(input:TradeInput,docs:TradeDoc[],catalogs:Catalog[],partners:Partner[],now=new Date().toISOString()):TradeDoc {
  const old=docs.find(d=>d.id===input.id);
  check(!old||old.state==='draft','Изменять можно только черновик.');
  check(!old||old.version===input.version,'Документ уже изменён. Обновите список и откройте его снова.');
  const ref=(id:string,kind:string)=>catalogs.find(c=>c.id===id&&c.kind===kind);
  check(ref(input.organization,'organization'),'Выберите организацию из текущей базы.');
  const payment=moneyKinds.includes(input.kind),warehouse=stockKinds.includes(input.kind)||isOrder({kind:input.kind} as TradeDoc);
  if(warehouse)check(ref(input.warehouse,'warehouse'),'Выберите склад.');
  if(input.kind==='transfer')check(input.target!==input.warehouse&&ref(input.target,'warehouse'),'Выберите другой склад-получатель.');
  if(!stockOnly.includes(input.kind)) {
    const partner=partners.find(p=>p.id===input.partner);check(partner,'Выберите контрагента из текущей базы.');
    const sale=['customer_order','invoice','sale','receipt'].includes(input.kind);
    check(partner?.role==='both'||partner?.role===(sale?'customer':'supplier'),sale?'Нужен контрагент с ролью покупателя.':'Нужен контрагент с ролью поставщика.');
  }
  check(!input.due||input.due>=input.date,'Срок должен быть не раньше даты документа.');
  const parent=docs.find(d=>d.id===input.basis);
  if(input.basis) {
    check(parent&&parent.state==='posted','Основание должно быть проведено.');
    check(parent?.organization===input.organization&&parent?.partner===input.partner,'Организация и контрагент должны совпадать с основанием.');
    check(input.date>=parent!.date,'Дата должна быть не раньше документа-основания.');
    const allowed:Partial<Record<TradeKind,TradeKind[]>>={invoice:['customer_order'],sale:['customer_order'],purchase:['supplier_order'],receipt:['customer_order','sale'],payment:['supplier_order','purchase','expense']};
    check(allowed[input.kind]?.includes(parent!.kind),'Это основание не подходит для документа.');
    check(!(payment&&parent!.basis),'Оплату нужно привязать к заказу, на основании которого создана накладная.');
  } else check(!payment&&input.kind!=='invoice','Выберите документ-основание.');
  let lines:TradeLine[]=[];
  if(!payment&&input.kind!=='expense') {
    check(input.lines.length>0&&input.lines.length<=50,'Добавьте от 1 до 50 товарных строк.');
    check(new Set(input.lines.map(l=>l.item)).size===input.lines.length,'Товар можно указать один раз; объедините количество в одной строке.');
    lines=input.lines.map(l=>{
      const item=ref(l.item,'product');check(item,'Номенклатура не найдена в текущей базе.');
      check(Number.isSafeInteger(l.qty)&&l.qty>0&&l.qty<=1000000000,'Количество должно быть положительным, не более 1 000 000.');
      check(finiteAmount(l.price),'Проверьте цену.');
      check(!stockOnly.includes(input.kind)||item!.item_type!=='service','Складские операции доступны только для товаров.');
      const amount=lineAmount(l.qty,l.price);check(finiteAmount(amount),'Сумма строки слишком большая.');
      if(parent&&['sale','purchase','invoice'].includes(input.kind)) {
        const origin=parent.lines.find(p=>p.item===l.item);
        check(origin&&origin.price===l.price,'Товар и цена должны соответствовать заказу.');
        check(l.qty<=origin!.qty,'Количество больше указанного в заказе.');
      }
      return {item:l.item,name:item!.name,unit:item!.unit,type:item!.item_type||'goods',qty:l.qty,price:l.price,amount,cost:0};
    });
  }
  const amount=payment||input.kind==='expense'?input.amount:lines.reduce((s,l)=>s+l.amount,0);
  check(finiteAmount(amount)&&(stockOnly.includes(input.kind)||amount>0),'Проверьте итоговую сумму документа.');
  const prefix:Record<TradeKind,string>={customer_order:'ЗП',supplier_order:'ЗС',invoice:'СЧ',sale:'РН',purchase:'ПН',receipt:'ПД',payment:'ОД',expense:'РС',transfer:'ПМ',stock_in:'ОП',stock_out:'СП'};
  const number=input.number.trim()||`${prefix[input.kind]}-${String(docs.filter(d=>d.kind===input.kind).length+1).padStart(5,'0')}`;
  check(!docs.some(d=>d.id!==input.id&&d.organization===input.organization&&d.kind===input.kind&&d.number===number),'Документ с таким номером уже есть у организации.');
  return {...input,number,partner:stockOnly.includes(input.kind)?'':input.partner,warehouse:warehouse?input.warehouse:'',target:input.kind==='transfer'?input.target:'',lines,amount,cost:0,state:'draft',sequence:0,reason:'',created:old?.created||now,version:(old?.version||0)+1};
}

export function postDocument(doc:TradeDoc,docs:TradeDoc[],sequence:number):TradeDoc {
  check(doc.state==='draft','Провести можно только черновик.');check(doc.date<=today(),'Нельзя провести документ будущей датой.');
  const parent=docs.find(d=>d.id===doc.basis);
  if(doc.basis)check(parent?.state==='posted','Документ-основание отменён.');
  if(moneyKinds.includes(doc.kind))check(doc.amount<=toPay(parent!,docs),'Сумма превышает остаток к оплате.');
  if(parent&&['sale','purchase'].includes(doc.kind)) for(const l of doc.lines) {
    const origin=parent.lines.find(p=>p.item===l.item);
    check(origin&&l.qty<=origin.qty-fulfilled(parent,l.item,docs),'Количество превышает остаток по заказу.');
  }
  const balances=stockRows(docs),lines=doc.lines.map(l=>({...l}));
  // Allocate rounded amounts cumulatively so splitting a fractional quantity
  // across several deliveries cannot create an extra kopeck of debt.
  if(parent&&['sale','purchase'].includes(doc.kind))for(const l of lines){
    const prior=docs.filter(d=>d.state==='posted'&&d.basis===parent.id&&d.kind===doc.kind).flatMap(d=>d.lines).filter(p=>p.item===l.item);
    const quantity=prior.reduce((s,p)=>s+p.qty,0),amount=prior.reduce((s,p)=>s+p.amount,0);
    l.amount=lineAmount(quantity+l.qty,l.price)-amount;
  }
  if(stockKinds.includes(doc.kind))for(const l of lines.filter(l=>l.type!=='service')) {
    const row=balances.find(r=>key(r.organization,r.warehouse,r.item)===key(doc.organization,doc.warehouse,l.item));
    const target=balances.find(r=>key(r.organization,r.warehouse,r.item)===key(doc.organization,doc.target,l.item));
    check(!row||doc.date>=row.date,`По товару «${l.name}» есть более позднее движение. Укажите дату не раньше ${row?.date}.`);
    if(doc.kind==='transfer')check(!target||doc.date>=target.date,'На складе-получателе есть более поздние движения.');
    if(['sale','transfer','stock_out'].includes(doc.kind)) {
      check(row&&row.qty>=l.qty,`Недостаточно товара «${l.name}»: доступно ${qtyText(row?.qty||0)} ${l.unit}.`);
      l.cost=l.qty===row!.qty?row!.value:Number((BigInt(row!.value)*BigInt(l.qty)+BigInt(Math.floor(row!.qty/2)))/BigInt(row!.qty));
    }
  }
  const cost=lines.reduce((s,l)=>s+l.cost,0);
  if(['transfer','stock_out'].includes(doc.kind))for(const l of lines){l.amount=l.cost;l.price=Math.round(l.cost*1000/l.qty);}
  return {...doc,lines,amount:['transfer','stock_out'].includes(doc.kind)?cost:parent&&['sale','purchase'].includes(doc.kind)?lines.reduce((s,l)=>s+l.amount,0):doc.amount,cost,state:'posted',sequence,version:doc.version+1};
}

export function voidDocument(doc:TradeDoc,docs:TradeDoc[],reason:string):TradeDoc {
  check(reason.trim().length>=3,'Укажите причину отмены.');check(doc.state!=='void','Документ уже отменён.');
  check(!docs.some(d=>d.basis===doc.id&&d.state!=='void'),'Сначала отмените связанные документы, включая черновики.');
  if(doc.state==='posted'&&doc.basis&&['sale','purchase'].includes(doc.kind))check(!docs.some(d=>d.state==='posted'&&d.kind===doc.kind&&d.basis===doc.basis&&d.sequence>doc.sequence&&d.lines.some(l=>doc.lines.some(p=>p.item===l.item))),'Сначала отмените более поздние поставки этих позиций по заказу.');
  if(doc.state==='posted'&&stockKinds.includes(doc.kind)) {
    const rows=stockRows(docs);
    for(const l of doc.lines.filter(l=>l.type!=='service'))for(const w of [doc.warehouse,...(doc.kind==='transfer'?[doc.target]:[])]) {
      const row=rows.find(r=>key(r.organization,r.warehouse,r.item)===key(doc.organization,w,l.item));
      check(row?.sequence===doc.sequence,'Сначала отмените более поздние складские движения этих товаров.');
    }
  }
  if(doc.state==='posted'&&['sale','purchase'].includes(doc.kind)&&doc.basis)check(!docs.some(d=>d.basis===doc.basis&&d.state==='posted'&&moneyKinds.includes(d.kind)),'Сначала отмените оплаты заказа.');
  return {...doc,state:'void',reason:reason.trim(),version:doc.version+1};
}

