import { CAPABILITY, bridgeRequest, dashboardSender, hostPermission, mayStart, publicationUrl, publicMessage, validateQueuedJob, withinPublication } from './core.js';
import { inspectPreparationTarget, showPreparationPanel } from './onec-panel.js';

let running = false;
chrome.storage.local.setAccessLevel({ accessLevel: 'TRUSTED_CONTEXTS' });

async function state() { return (await chrome.storage.local.get(['config', 'execution'])); }
async function saveExecution(execution) { await chrome.storage.local.set({ execution }); }
async function status() {
  const { config, execution } = await state();
  const configured = Boolean(config?.publication && await chrome.permissions.contains({ origins: [hostPermission(config.publication)] }));
  return { ...CAPABILITY, configured, paused: config?.paused !== false,
    execution: execution?.active ? { jobId: execution.active.jobId, state: execution.active.state, message: execution.active.message } : null };
}
async function api(tabId, action, body) {
  const tab = await chrome.tabs.get(tabId);
  if (!dashboardSender({ frameId: 0, tab, url: tab.url })) throw new Error('Вкладка Atlas закрыта или сменила адрес.');
  const response = await chrome.tabs.sendMessage(tabId, { type: 'jobs-api', action, body }, { frameId: 0 });
  if (!response?.ok) throw new Error(response?.error || 'Очередь не ответила. Автоповтор запрещён.');
  return response.data;
}

async function run(tabId, id) {
  if (running) throw new Error('Другой запуск уже выполняется.');
  running = true;
  let execution;
  try {
    const current = await state();
    execution = current.execution || { active: null, history: {} };
    mayStart(execution, id);
    const config = current.config;
    if (!config?.publication || config.paused !== false) throw new Error('Откройте настройки помощника, укажите 1С и снимите паузу.');
    const publication = publicationUrl(config.publication);
    if (!await chrome.permissions.contains({ origins: [hostPermission(publication)] })) throw new Error('Доступ к выбранному адресу 1С не разрешён.');
    const tabs = (await chrome.tabs.query({ url: hostPermission(publication) })).filter((tab) => withinPublication(tab.url, publication));
    if (!tabs.length) throw new Error('Сначала откройте свою публикацию 1С и войдите. Задание не запускалось; после входа можно повторно нажать подготовку.');
    if (tabs.length > 1) throw new Error('Открыто несколько вкладок этой публикации 1С. Закройте лишние. Задание не запускалось.');
    const preflight = await chrome.scripting.executeScript({ target: { tabId: tabs[0].id, frameIds: [0] }, func: inspectPreparationTarget, args: [publication] });
    if (preflight.length !== 1 || preflight[0].result?.ready !== true) throw new Error(preflight[0]?.result?.existingPanel
      ? 'В 1С уже открыта карточка Atlas. Сначала проверьте её и закройте. Новое задание не запускалось.'
      : 'Войдите в 1С и откройте форму «Заказ покупателя (создание)». Поддерживаемая форма не найдена; задание не запускалось.');
    const queue = await api(tabId, 'get');
    const matching = queue.jobs?.filter((job) => job.id === id);
    if (matching?.length !== 1) throw new Error('Задание очереди не найдено однозначно.');
    const job = validateQueuedJob(matching[0]);
    const runId = crypto.randomUUID();
    // Write before claim/injection. A restart or uncertain response leaves this lock in place.
    execution.active = { jobId: id, runId, state: 'claiming', at: new Date().toISOString(), message: 'Запуск начат. Не повторять без проверки.' };
    execution.history[id] = { runId, state: 'claiming', at: execution.active.at };
    await saveExecution(execution);
    const claimed = await api(tabId, 'claim', { revision: queue.revision, id, runId });
    const claimedJobs = claimed?.jobs?.filter((candidate) => candidate.id === id);
    if (!Number.isSafeInteger(claimed?.revision) || claimedJobs?.length !== 1 || claimedJobs[0].status !== 'running' || claimedJobs[0].runId !== runId || claimedJobs[0].marker !== job.marker) {
      throw new Error('Сервер не подтвердил владение запуском. Проверьте очередь вручную.');
    }
    execution.active.state = 'preparing';
    execution.history[id].state = 'preparing';
    await saveExecution(execution);
    let message;
    try {
      const tab = await chrome.tabs.get(tabs[0].id);
      if (!withinPublication(tab.url, publication)) throw new Error('Адрес вкладки 1С изменился.');
      const check = await state();
      if (check.config?.paused !== false || check.config.publication !== publication) throw new Error('Настройки изменились или помощник поставлен на паузу.');
      const recheck = await chrome.scripting.executeScript({ target: { tabId: tab.id, frameIds: [0] }, func: inspectPreparationTarget, args: [publication] });
      if (recheck.length !== 1 || recheck[0].result?.ready !== true) throw new Error('Форма 1С изменилась после начала запуска. Требуется ручная проверка.');
      const result = await chrome.scripting.executeScript({ target: { tabId: tab.id, frameIds: [0] }, func: showPreparationPanel, args: [publication, job] });
      if (result.length !== 1 || result[0].result?.panelVisible !== true) throw new Error('Карточка не подтверждена во вкладке 1С.');
      await chrome.tabs.update(tab.id, { active: true });
      message = 'Карточка снимка показана в 1С. Автоматическое создание и сохранение отключены: точное сопоставление справочников и проверка результата записи ещё не подтверждены. Требуется ручная проверка и запись без проведения.';
    } catch (error) { message = publicMessage(error); }
    execution.active.state = 'reporting_attention'; execution.active.message = message;
    await saveExecution(execution);
    if (claimed?.revision === undefined) throw new Error('Ответ claim не содержит версию очереди. Повтор отключён.');
    await api(tabId, 'attention', { revision: claimed.revision, id, runId, message });
    execution.history[id] = { ...execution.history[id], state: 'needs_attention' };
    execution.active = null;
    await saveExecution(execution);
    return { ...await status(), state: 'needs_attention', jobId: id, message };
  } catch (error) {
    if (execution?.active?.jobId === id) {
      execution.active.state = 'unknown'; execution.active.message = `${publicMessage(error)} Проверьте очередь и 1С вручную; повтор заблокирован.`;
      execution.history[id].state = 'unknown';
      await saveExecution(execution);
    }
    throw error;
  } finally { running = false; }
}

chrome.runtime.onMessage.addListener((message, sender, respond) => {
  if (sender.id !== chrome.runtime.id || message?.type !== 'dashboard' || !dashboardSender(sender) || !bridgeRequest(message.request)) return;
  const request = message.request;
  (request.action === 'status' ? status() : run(sender.tab.id, request.jobId))
    .then((value) => respond({ ok: true, status: value }))
    .catch((error) => respond({ ok: false, error: publicMessage(error) }));
  return true;
});

