export const DASHBOARD_ORIGIN = 'https://atlas-trade-workspace.vagram663.chatgpt.site';
export const CHANNEL = 'atlas-onec';
export const CAPABILITY = Object.freeze({ installed: true, autoSave: false, mode: 'prepare-only' });

export function publicMessage(error) {
  return String(error?.message || 'Неизвестная ошибка помощника.').replace(/https?:\/\/[^\s"'<>]+/gi, '[локальный адрес]').slice(0, 900);
}

export function publicationUrl(value) {
  if (typeof value !== 'string' || !value.trim()) throw new Error('Укажите адрес публикации 1С.');
  const url = new URL(value.trim());
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password || url.search || url.hash) {
    throw new Error('Нужен HTTP(S)-адрес без пароля, параметров и фрагмента.');
  }
  if (url.origin === DASHBOARD_ORIGIN) throw new Error('Адрес 1С должен отличаться от адреса Atlas.');
  url.pathname = `${url.pathname.replace(/\/+$/, '')}/`;
  return url.href;
}

export function hostPermission(value) { return `${new URL(publicationUrl(value)).origin}/*`; }

export function withinPublication(value, configured) {
  try {
    const url = new URL(value);
    const base = new URL(publicationUrl(configured));
    return !url.username && !url.password && url.origin === base.origin &&
      (url.pathname === base.pathname.slice(0, -1) || url.pathname.startsWith(base.pathname));
  } catch { return false; }
}

export function bridgeRequest(value) {
  return Boolean(value && value.channel === CHANNEL && value.response !== true &&
    typeof value.requestId === 'string' && /^[a-zA-Z0-9_-]{1,100}$/.test(value.requestId) &&
    ['status', 'run'].includes(value.action) &&
    (value.action === 'status' || typeof value.jobId === 'string' && /^[a-zA-Z0-9_-]{1,100}$/.test(value.jobId)));
}

export function dashboardSender(sender) {
  try { return sender.frameId === 0 && Number.isInteger(sender.tab?.id) &&
    new URL(sender.url).origin === DASHBOARD_ORIGIN && new URL(sender.tab.url).origin === DASHBOARD_ORIGIN;
  } catch { return false; }
}

export function validateQueuedJob(job) {
  if (!job || job.status !== 'queued' || typeof job.id !== 'string' || !/^ATLAS-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(job.marker)) {
    throw new Error('Задание не готово к запуску или не содержит корректного маркера.');
  }
  const s = job.snapshot;
  if (!s || !s.documentId || !s.partner?.id || !s.partner?.name || !s.partner?.inn ||
    !s.organization?.id || !s.organization?.name || !s.warehouse?.id || !s.warehouse?.name ||
    !Array.isArray(s.lines) || !s.lines.length || !Number.isSafeInteger(s.amount) || s.amount < 0) {
    throw new Error('В снимке не хватает реквизитов для однозначного сопоставления с 1С.');
  }
  let total = 0;
  for (const line of s.lines) {
    if (!line.item || !line.name || !(line.code || line.article) || !line.unit ||
      !Number.isSafeInteger(line.qty) || line.qty <= 0 || !Number.isSafeInteger(line.price) || line.price < 0 ||
      !Number.isSafeInteger(line.amount) || line.amount < 0) throw new Error('Строка заказа неполная.');
    total += line.amount;
    if (!Number.isSafeInteger(total)) throw new Error('Сумма заказа слишком велика.');
  }
  if (total !== s.amount) throw new Error('Сумма строк не совпадает с суммой снимка.');
  return job;
}

export function mayStart(record, jobId) {
  if (record?.active) throw new Error('Предыдущий запуск требует проверки. Автоповтор заблокирован.');
  if (record?.history?.[jobId]) throw new Error('Это задание уже запускалось на этом ПК. Повтор заблокирован.');
  if (Object.keys(record?.history ?? {}).length >= 1000) throw new Error('Локальный журнал заполнен. Требуется обслуживание.');
}

