export function inspectPreparationTarget(publication) {
  const base = new URL(publication), here = new URL(location.href);
  if (window !== window.top || here.origin !== base.origin || here.username || here.password ||
    !(here.pathname === base.pathname.slice(0, -1) || here.pathname.startsWith(base.pathname))) return { ready: false };
  if (document.getElementById('atlas-onec-preparation')) return { ready: false, existingPanel: true };
  const visible = (node) => !!node?.getClientRects().length;
  const buyers = [...document.querySelectorAll('[id$="_Контрагент_i0"]')].filter(visible);
  if (buyers.length !== 1 || !document.body?.innerText.includes('Заказ покупателя (создание)')) return { ready: false };
  const prefix = buyers[0].id.slice(0, -'_Контрагент_i0'.length);
