import { hostPermission, publicationUrl } from './core.js';
const form = document.querySelector('#settings');
const input = document.querySelector('#publication');
const enabled = document.querySelector('#enabled');
const message = document.querySelector('#message');
async function refresh() {
  const { config, execution } = await chrome.storage.local.get(['config', 'execution']);
  input.value = config?.publication || '';
  enabled.checked = config?.paused === false;
  document.querySelector('#execution').textContent = execution?.active
    ? `Требуется проверка: ${execution.active.jobId}\n${execution.active.message}`
    : `Локальная блокировка отсутствует. Запусков в истории: ${Object.keys(execution?.history ?? {}).length}.`;
}
form.addEventListener('submit', async (event) => {
  event.preventDefault();
  try {
    const publication = publicationUrl(input.value);
    // Permission request must be the direct consequence of this user gesture.
    const granted = await chrome.permissions.request({ origins: [hostPermission(publication)] });
    if (!granted) throw new Error('Доступ не разрешён. Настройки не изменены.');
    const previous = (await chrome.storage.local.get('config')).config;
    await chrome.storage.local.set({ config: { publication, paused: !enabled.checked } });
    if (previous?.publication && hostPermission(previous.publication) !== hostPermission(publication)) {
      await chrome.permissions.remove({ origins: [hostPermission(previous.publication)] });
    }
    message.textContent = enabled.checked ? 'Настройки сохранены. Доступна только подготовка по кнопке Atlas.' : 'Настройки сохранены. Помощник на паузе.';
    await refresh();
  } catch (error) { message.textContent = error.message; }
});
document.querySelector('#pause').addEventListener('click', async () => {
  const { config } = await chrome.storage.local.get('config');
  await chrome.storage.local.set({ config: { ...config, paused: true } });
  message.textContent = 'Новые действия остановлены. Уже показанная карточка и история запусков сохранены.';
  await refresh();
});
document.querySelector('#disconnect').addEventListener('click', async () => {
  const { config } = await chrome.storage.local.get('config');
  await chrome.storage.local.set({ config: { paused: true } });
  if (config?.publication) await chrome.permissions.remove({ origins: [hostPermission(config.publication)] });
  message.textContent = 'Адрес удалён, разрешение отозвано. История запусков сохранена.';
  await refresh();
});
refresh();

