async function stableId(owner:string,key:string){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(owner+'|atlas-demo-v1|'+key));let h=Array.from(new Uint8Array(bytes),n=>n.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-4${h.slice(13,16)}-a${h.slice(17,20)}-${h.slice(20,32)}`;}
export async function seedDemo(owner:string){
 const d=db(),data=demoData(),all=[...data.partners,...data.catalogs,...data.documents];const ids=Object.fromEntries(await Promise.all(all.map(async r=>[r.key,await stableId(owner,r.key)])));const now=new Date().toISOString();
 const statements=[...data.partners.map(p=>d.prepare('INSERT OR IGNORE INTO partners(id,owner,name,inn,role,contact,created) VALUES(?,?,?,?,?,?,?)').bind(ids[p.key],owner,p.name,p.inn,p.role,p.contact,now)),...data.catalogs.map(c=>d.prepare('INSERT OR IGNORE INTO catalogs(id,owner,kind,code,name,unit,price,note,created) VALUES(?,?,?,?,?,?,?,?,?)').bind(ids[c.key],owner,c.kind,c.code,c.name,c.unit,c.price,c.note,now)),...data.documents.map(r=>d.prepare('INSERT OR IGNORE INTO documents(id,owner,kind,number,date,due,partner,amount,cost,note,link,state,created,posted,void_reason,organization,warehouse,item,category) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(ids[r.key],owner,r.kind,r.number,r.date,r.due,ids[r.partner],r.amount,r.cost,r.note,r.link?ids[r.link]:'',r.state,now,r.state==='posted'?now:null,r.state==='void'?'Учебный пример отменённого документа':'',ids[r.organization]||'',ids[r.warehouse]||'',ids[r.item]||'',ids[r.category]||''))];
 await d.batch(statements);return {partners:data.partners.length,catalogs:data.catalogs.length,documents:data.documents.length};
}

