import { db } from './raw';
import { emptyOneCJobsWorkspace,markStaleOneCJobs,OneCJobError,type OneCJobsWorkspace } from '../app/onec-jobs';

const MAX_BODY_BYTES=1_500_000;
export async function readOneCJobs(owner:string,now=new Date().toISOString()):Promise<OneCJobsWorkspace>{
  const d=db();
  await d.prepare('INSERT OR IGNORE INTO onec_job_workspaces(owner,body,revision) VALUES(?,?,0)').bind(owner,JSON.stringify(emptyOneCJobsWorkspace())).run();
  for(let attempt=0;attempt<3;attempt++){
    const row=await d.prepare('SELECT body,revision FROM onec_job_workspaces WHERE owner=?').bind(owner).first<{body:string;revision:number}>();
    if(!row)throw new Error('ONEC_QUEUE_UNAVAILABLE');
    const current={...(JSON.parse(row.body) as OneCJobsWorkspace),revision:Number(row.revision)},next=markStaleOneCJobs(current,now);
    if(next===current)return current;
    next.revision=current.revision+1;
    if(await writeOneCJobs(owner,current.revision,next))return next;
  }
  throw new OneCJobError('Очередь изменилась во время проверки. Повторите запрос.');
}
export async function writeOneCJobs(owner:string,revision:number,workspace:OneCJobsWorkspace):Promise<boolean>{
  const body=JSON.stringify(workspace);
  if(new TextEncoder().encode(body).byteLength>MAX_BODY_BYTES)throw new OneCJobError('Очередь заполнена. Обратитесь к администратору для архивирования истории.');
  const result=await db().prepare('UPDATE onec_job_workspaces SET body=?,revision=revision+1 WHERE owner=? AND revision=?').bind(body,owner,revision).run();
  return result.meta.changes===1;
}

