import {db} from './raw';
import {editableRequest,type SalesRequest,type generateRequestDocuments} from '../app/sales-requests';

const normalize=(r:SalesRequest):SalesRequest=>({...r,...editableRequest(r)});
export async function readSalesRequests(owner:string):Promise<SalesRequest[]>{
  const rows=await db().prepare('SELECT body FROM sales_requests WHERE owner=? ORDER BY updated DESC,id').bind(owner).all<{body:string}>();
  return rows.results.map(r=>normalize(JSON.parse(r.body) as SalesRequest));
}
export async function findSalesRequest(id:string):Promise<{owner:string;request:SalesRequest}|null>{
  const row=await db().prepare('SELECT owner,body FROM sales_requests WHERE id=?').bind(id).first<{owner:string;body:string}>();
  return row?{owner:row.owner,request:normalize(JSON.parse(row.body) as SalesRequest)}:null;
}
export async function writeSalesRequest(owner:string,previousVersion:number,request:SalesRequest):Promise<boolean>{
  const d=db(),body=JSON.stringify(request);
  const result=previousVersion===0
    ?await d.prepare('INSERT INTO sales_requests(id,owner,version,body,updated) SELECT ?,?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM sales_requests WHERE id=?) AND (SELECT COUNT(*) FROM sales_requests WHERE owner=?)<200').bind(request.id,owner,request.version,body,request.updated,request.id,owner).run()
    :await d.prepare('UPDATE sales_requests SET version=?,body=?,updated=? WHERE id=? AND owner=? AND version=?').bind(request.version,body,request.updated,request.id,owner,previousVersion).run();
  return result.meta.changes===1;
}
export async function commitRequestDocuments(owner:string,previousVersion:number,tradeRevision:number,generated:ReturnType<typeof generateRequestDocuments>):Promise<boolean>{
  const d=db(),r=generated.request,token=r.generated!.customerOrder;
  // The first CAS acquires this request within the D1 batch transaction. Validate
  // mutable catalogue/member references again in SQL, before recording approval's
  // exact document IDs. All subsequent writes require that unique token.
  const statements=[d.prepare(`UPDATE sales_requests AS r SET version=?,body=?,updated=?
    WHERE r.id=? AND r.owner=? AND r.version=? AND json_extract(r.body,'$.state')='approved'
    AND EXISTS(SELECT 1 FROM trade_revisions WHERE owner=r.owner AND revision=?)
    AND EXISTS(SELECT 1 FROM partners WHERE id=json_extract(r.body,'$.partner') AND owner=r.owner AND role IN ('customer','both'))
    AND NOT EXISTS(SELECT 1 FROM json_each(r.body,'$.lines') sl WHERE NOT EXISTS(SELECT 1 FROM partners WHERE id=COALESCE(NULLIF(json_extract(sl.value,'$.supplier'),''),json_extract(r.body,'$.supplier')) AND owner=r.owner AND role IN ('supplier','both')))
    AND NOT EXISTS(SELECT 1 FROM json_each(r.body,'$.lines') pl WHERE COALESCE(json_extract(pl.value,'$.priceBatchId'),'')!='' AND NOT EXISTS(SELECT 1 FROM supplier_price_batches pb,json_each(pb.body,'$.rows') pr WHERE pb.id=json_extract(pl.value,'$.priceBatchId') AND pb.version=json_extract(pl.value,'$.priceBatchVersion') AND pb.owner=r.owner AND json_extract(pb.body,'$.active')=1 AND json_extract(pb.body,'$.supplier')=COALESCE(NULLIF(json_extract(pl.value,'$.supplier'),''),json_extract(r.body,'$.supplier')) AND json_extract(pr.value,'$.id')=json_extract(pl.value,'$.priceRowId') AND json_extract(pr.value,'$.price')=json_extract(pl.value,'$.buyPrice') AND json_extract(pr.value,'$.unit')=json_extract(pl.value,'$.unit') AND json_extract(pr.value,'$.name')=json_extract(pl.value,'$.supplierItemName')))
    AND EXISTS(SELECT 1 FROM catalogs WHERE id=json_extract(r.body,'$.organization') AND owner=r.owner AND kind='organization')
    AND EXISTS(SELECT 1 FROM catalogs WHERE id=json_extract(r.body,'$.warehouse') AND owner=r.owner AND kind='warehouse')
    AND (json_extract(r.body,'$.assignee')='' OR EXISTS(SELECT 1 FROM sales_workspaces w,json_each(w.body,'$.members') m WHERE w.owner=r.owner AND json_extract(m.value,'$.id')=json_extract(r.body,'$.assignee') AND json_extract(m.value,'$.active')=1))
    AND NOT EXISTS(SELECT 1 FROM json_each(r.body,'$.lines') l WHERE json_extract(l.value,'$.item')!='' AND NOT EXISTS(SELECT 1 FROM catalogs c WHERE c.id=json_extract(l.value,'$.item') AND c.owner=r.owner AND c.kind='product' AND c.item_type='goods' AND c.name=json_extract(l.value,'$.name') AND c.unit=json_extract(l.value,'$.unit')))`)
    .bind(r.version,JSON.stringify(r),r.updated,r.id,owner,previousVersion,tradeRevision)];
  const guard=`EXISTS(SELECT 1 FROM sales_requests WHERE id=? AND owner=? AND version=? AND json_extract(body,'$.generated.customerOrder')=?) AND EXISTS(SELECT 1 FROM trade_revisions WHERE owner=? AND revision=?)`;
  const args=[r.id,owner,r.version,token,owner,tradeRevision];
  for(const c of generated.newCatalogs)statements.push(d.prepare(`INSERT INTO catalogs(id,owner,kind,code,name,unit,price,note,item_type,details,created) SELECT ?,?,?,?,?,?,?,?,?,?,? WHERE ${guard}`).bind(c.id,owner,c.kind,c.code,c.name,c.unit,c.price,c.note,'goods','{}',r.updated,...args));
  for(const doc of generated.documents)statements.push(d.prepare(`INSERT INTO trade_documents(id,owner,body) SELECT ?,?,? WHERE ${guard}`).bind(doc.id,owner,JSON.stringify(doc),...args));
  statements.push(d.prepare(`UPDATE trade_revisions SET revision=revision+1 WHERE owner=? AND revision=? AND EXISTS(SELECT 1 FROM sales_requests WHERE id=? AND owner=? AND version=? AND json_extract(body,'$.generated.customerOrder')=?)`).bind(owner,tradeRevision,r.id,owner,r.version,token));
  // Plain INSERT deliberately aborts (and rolls back the entire batch) on any
  // global UUID collision; never overwrite an existing owner's row.
  const result=await d.batch(statements);
  return result[0].meta.changes===1&&result.at(-1)!.meta.changes===1;
}

