import { db } from './raw';
import { emptySalesWorkspace, SalesError, type SalesWorkspace } from '../app/sales-team';

export async function readSalesWorkspace(owner:string):Promise<SalesWorkspace> {
  const d=db();
  await d.prepare('INSERT OR IGNORE INTO sales_workspaces(owner,body,revision) VALUES(?,?,0)').bind(owner,JSON.stringify(emptySalesWorkspace())).run();
  const row=await d.prepare('SELECT body,revision FROM sales_workspaces WHERE owner=?').bind(owner).first<{body:string;revision:number}>();
  if(!row)throw new Error('SALES_WORKSPACE_UNAVAILABLE');
  return {...JSON.parse(row.body) as SalesWorkspace,revision:row.revision};
}
export async function writeSalesWorkspace(owner:string,revision:number,workspace:SalesWorkspace):Promise<boolean> {
  const body=JSON.stringify({...workspace,revision:revision+1});
  if(new TextEncoder().encode(body).byteLength>1500000)throw new SalesError('Рабочее пространство заполнено. Сократите заметки и результаты задач.');
  // A single compare-and-swap statement commits the body and revision together.
  const result=await db().prepare('UPDATE sales_workspaces SET body=?,revision=revision+1 WHERE owner=? AND revision=?').bind(body,owner,revision).run();
  return result.meta.changes===1;
}

