import type { Catalog,Partner } from '../app/logic';
export async function tradeSeed(owner:string,catalogs:Catalog[],partners:Partner[]) {
  const org=catalogs.find(c=>c.kind==='organization'),warehouses=catalogs.filter(c=>c.kind==='warehouse'),products=catalogs.filter(c=>c.kind==='product'&&c.item_type!=='service').slice(0,2);
  const customer=partners.find(p=>p.role==='customer'||p.role==='both'),supplier=partners.find(p=>p.role==='supplier'&&p.name.includes('Металл'))||partners.find(p=>p.role==='supplier'||p.role==='both');
  if(!org||!warehouses.length||products.length<2||!customer||!supplier)return [];
  const documents:TradeDoc[]=[],date=new Date().toISOString().slice(0,10),due=new Date(Date.now()+7*86400000).toISOString().slice(0,10);
  async function add(k:string,kind:TradeKind,values:Partial<TradeInput>={},posted=true){
    const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(owner+'|atlas-trade-demo-v1|'+k));const h=Array.from(new Uint8Array(digest),v=>v.toString(16).padStart(2,'0')).join('');
    const id=`${h.slice(0,8)}-${h.slice(8,12)}-4${h.slice(13,16)}-a${h.slice(17,20)}-${h.slice(20,32)}`;
    let d=makeDraft({id,version:0,kind,number:'ТЕСТ-'+k,date,due,organization:org!.id,warehouse:warehouses[0].id,target:'',partner:customer!.id,basis:'',note:'Учебный торговый цикл. Вымышленные данные.',amount:0,channel:'bank',lines:[],...values},documents,catalogs,partners);
    if(posted)d=postDocument(d,documents,documents.length+1);documents.push(d);return d;
  }
  const goods=(q1:number,q2:number,retail=false)=>products.map((p,i)=>({item:p.id,qty:(i?q2:q1)*1000,price:i?(retail?850:500):(retail?2500:1400)})).filter(l=>l.qty>0);
  await add('ОП-01','stock_in',{lines:goods(1000,800)});
  const so=await add('ЗС-01','supplier_order',{partner:supplier.id,lines:goods(500,200)});
  await add('ПН-01','purchase',{basis:so.id,partner:supplier.id,lines:goods(300,100)});
  const co=await add('ЗП-01','customer_order',{lines:goods(200,80,true)});
  await add('СЧ-01','invoice',{basis:co.id,lines:goods(200,80,true)});
  await add('РН-01','sale',{basis:co.id,lines:goods(120,30,true)});
  await add('ПД-01','receipt',{basis:co.id,amount:200000});
  await add('ОД-01','payment',{basis:so.id,partner:supplier.id,amount:300000});
  if(warehouses[1])await add('ПМ-01','transfer',{target:warehouses[1].id,lines:goods(50,50)});
  await add('СП-01','stock_out',{lines:goods(0,2),note:'Учебный пример списания брака.'});
  const expense=await add('РС-01','expense',{partner:supplier.id,amount:150000,note:'Учебный пример расходов на доставку.'});
  await add('ОД-02','payment',{basis:expense.id,partner:supplier.id,amount:150000,channel:'cash'});
  await add('ЗП-02','customer_order',{lines:goods(150,200,true)},false);
  await add('ЗС-02','supplier_order',{partner:supplier.id,lines:goods(200,150)},false);
  return documents;
}

