import { db } from './raw';
import type { TradeDoc } from '../app/trade';
import type { Catalog, Partner } from '../app/logic';

// Read the revision and the documents in one snapshot. Every trade write uses
// the same owner revision, so stock, payments and order quantities cannot race.
export async function readTrade(owner:string) {
  const d=db();
  await d.prepare('INSERT OR IGNORE INTO trade_revisions(owner,revision) VALUES(?,0)').bind(owner).run();
  const [r,docs,c,p]=await d.batch([
    d.prepare('SELECT revision FROM trade_revisions WHERE owner=?').bind(owner),
    d.prepare('SELECT body FROM trade_documents WHERE owner=?').bind(owner),
    d.prepare('SELECT * FROM catalogs WHERE owner=? ORDER BY code').bind(owner),
    d.prepare('SELECT * FROM partners WHERE owner=? ORDER BY name').bind(owner),
  ]);
  return {revision:Number((r.results[0] as {revision:number}).revision),documents:docs.results.map(row=>JSON.parse(String((row as {body:string}).body)) as TradeDoc),catalogs:c.results as unknown as Catalog[],partners:p.results as unknown as Partner[]};
}
export async function writeTrade(owner:string,revision:number,docs:TradeDoc[]) {
  const d=db();
  const statements=docs.map(doc=>d.prepare(`INSERT INTO trade_documents(id,owner,body)
    SELECT ?,?,? WHERE EXISTS(SELECT 1 FROM trade_revisions WHERE owner=? AND revision=?)
    ON CONFLICT(id) DO UPDATE SET body=excluded.body WHERE trade_documents.owner=excluded.owner`).bind(doc.id,owner,JSON.stringify(doc),owner,revision));
  statements.push(d.prepare('UPDATE trade_revisions SET revision=revision+1 WHERE owner=? AND revision=?').bind(owner,revision));
  const result=await d.batch(statements);
  return result.at(-1)!.meta.changes===1;
}

