    "onec-panel.js": "// Executed in the isolated world of the explicitly configured 1C publication.
// This adapter never clicks or changes 1C controls, and never saves/posts documents.
export function inspectPreparationTarget(publication) {
  const base = new URL(publication), here = new URL(location.href);
  if (window !== window.top || here.origin !== base.origin || here.username || here.password ||
    !(here.pathname === base.pathname.slice(0, -1) || here.pathname.startsWith(base.pathname))) return { ready: false };
  if (document.getElementById('atlas-onec-preparation')) return { ready: false, existingPanel: true };
  const visible = (node) => !!node?.getClientRects().length;
  const buyers = [...document.querySelectorAll('[id$="_Контрагент_i0"]')].filter(visible);
  if (buyers.length !== 1 || !document.body?.innerText.includes('Заказ покупателя (создание)')) return { ready: false };
  const prefix = buyers[0].id.slice(0, -'_Контрагент_i0'.length);
  if (!/^form\d+$/.test(prefix)) return { ready: false };
  return { ready: ['_Организация_i0', '_СтруктурнаяЕдиницаРезерв_i0', '_ФормаЗаписать'].every((suffix) => visible(document.getElementById(prefix + suffix))) };
}

export function showPreparationPanel(publication, job) {
  const base = new URL(publication);
  const here = new URL(location.href);
  if (window !== window.top || here.origin !== base.origin || here.username || here.password ||
    !(here.pathname === base.pathname.slice(0, -1) || here.pathname.startsWith(base.pathname))) {
    throw new Error('Вкладка покинула разрешённую публикацию 1С.');
  }
  const panelId = 'atlas-onec-preparation';
  if (document.getElementById(panelId)) throw new Error('Во вкладке уже открыта карточка Atlas. Закройте её после проверки.');
  const host = document.createElement('aside');
  host.id = panelId;
  const root = host.attachShadow({ mode: 'closed' });
