import { CAPABILITY, DASHBOARD_ORIGIN, bridgeRequest, dashboardSender, hostPermission, mayStart, publicationUrl, publicMessage, validateQueuedJob, withinPublication } from '../companion/core.js';

const marker = 'ATLAS-01234567-89ab-cdef-0123-456789abcdef';
const job = () => ({ id: 'job-1', marker, status: 'queued', snapshot: { documentId: 'order-1',
  partner: { id: 'p1', name: 'Buyer', inn: '1234567890' }, organization: { id: 'o1', name: 'Org' }, warehouse: { id: 'w1', name: 'Warehouse' },
  lines: [{ item: 'i1', name: 'Item', code: 'SKU-1', article: '', unit: 'шт', qty: 2000, price: 500, amount: 1000 }], amount: 1000 } });

test('publication config has no secret-bearing or non-HTTP URLs', () => {
  assert.equal(publicationUrl('https://example.test:8443/base'), 'https://example.test:8443/base/');
  assert.equal(hostPermission('https://example.test/base'), 'https://example.test/*');
  for (const bad of ['', 'file:///secret', 'javascript:alert(1)', 'https://user:secret@example.test/base', 'https://example.test/base?token=x', 'https://example.test/base#token', DASHBOARD_ORIGIN]) {
    assert.throws(() => publicationUrl(bad));
  }
});
test('native errors do not disclose configured publication URLs to the dashboard or server', () => {
  const safe = publicMessage(new Error('Cannot access "http://example.test:8080/private/base" or https://example.test/secret'));
  assert.doesNotMatch(safe, /example\.test|8080|private|secret/);
  assert.equal(publicMessage(new Error('x'.repeat(2000))).length, 900);
});
