  const base = 'http://example.test:8080/base/';
  for (const allowed of [`${base}en_US/`, `${base}?v=1`, base.slice(0, -1)]) assert.equal(withinPublication(allowed, base), true);
  for (const bad of ['https://example.test:8080/base/', 'http://example.test/base/', 'http://evil.test:8080/base/', 'http://example.test:8080/base-other/', 'http://example.test:8080/base%2Fother/', 'http://user@example.test:8080/base/', 'http://example.test:8080/base/../other/']) assert.equal(withinPublication(bad, base), false);
});
test('bridge requires exact channel, action and bounded correlation ID', () => {
  assert.equal(bridgeRequest({ channel: 'atlas-onec', requestId: 'req_1', action: 'status' }), true);
  assert.equal(bridgeRequest({ channel: 'atlas-onec', requestId: 'req_1', action: 'run', jobId: 'job-1' }), true);
  for (const override of [{ response: true }, { action: 'save' }, { requestId: 'x'.repeat(101) }, { requestId: '<script>' }, { channel: 'evil' }]) assert.equal(bridgeRequest({ channel: 'atlas-onec', requestId: 'r', action: 'status', ...override }), false);
  assert.equal(bridgeRequest({ channel: 'atlas-onec', requestId: 'r', action: 'run' }), false);
