  assert.equal(dashboardSender(sender), true);
  assert.equal(dashboardSender({ ...sender, frameId: 1 }), false);
  assert.equal(dashboardSender({ ...sender, url: `${DASHBOARD_ORIGIN}.evil.test/` }), false);
  assert.equal(dashboardSender({ ...sender, tab: { id: 12, url: 'https://evil.test/' } }), false);
  assert.equal(dashboardSender({ frameId: 0, url: sender.url }), false);
