const partners=[{id:'c1',name:'Покупатель',role:'customer'},{id:'p1',name:'Поставщик',role:'supplier'}];
function env(){const docs=[];let n=0;return {docs,create(kind,extra={},post=true){let d=makeDraft({id:'id'+(++n),version:0,kind,number:'',date,due:'',organization:org,warehouse:w,target:'',partner:'c1',basis:'',note:'',channel:'bank',amount:0,lines:[{item,qty:10000,price:200}],...extra},docs,catalogs,partners);docs.push(d);if(post){d=postDocument(d,docs,n);docs[docs.length-1]=d;}return d;},replace(d){docs[docs.findIndex(x=>x.id===d.id)]=d;}};}
