 const e=env();e.create('stock_in',{lines:[{item,qty:10000,price:100}]});e.create('purchase',{partner:'p1',lines:[{item,qty:10000,price:300}]});
 const sale=e.create('sale',{lines:[{item,qty:5000,price:500}]});assert.equal(sale.amount,2500);assert.equal(sale.cost,1000);
 const tr=e.create('transfer',{target:'w2',lines:[{item,qty:3000,price:0}]});assert.equal(tr.cost,600);assert.equal(tr.amount,600);
 const loss=e.create('stock_out',{lines:[{item,qty:2000,price:0}]});assert.equal(loss.cost,400);
 assert.deepEqual(stockRows(e.docs).map(r=>[r.warehouse,r.qty,r.value]),[['w1',10000,2000],['w2',3000,600]]);
 assert.equal(tradeReport(e.docs,date.slice(0,7)).profit,1100);
 const tooMuch=e.create('sale',{lines:[{item,qty:11000,price:500}]},false);assert.throws(()=>postDocument(tooMuch,e.docs,20),/Недостаточно/);
});
